    <input
      type="search"
      className="search-input"
      value={text}
      placeholder={props.placeholder ?? 'Search…'}
      autoFocus={props.autoFocus}
      onChange={(e) => handleChange(e.target.value)}
      aria-label="Search"
    />
  );
}

