export function createQueue<T>(worker: (item: T) => Promise<void>) {
  const items: T[] = [];
  let running = false;
  const waiters: Array<() => void> = [];

  async function pump() {
    if (running) return;
    running = true;
    while (items.length > 0) {
      const item = items.shift()!;
      try { await worker(item); } catch { /* worker handles its own errors */ }
    }
    running = false;
    waiters.splice(0).forEach((w) => w());
  }

  return {
    push(item: T) {
      items.push(item);
      void pump();
      return new Promise<void>((resolve) => {
        const check = () => { if (!running && items.length === 0) resolve(); };
        waiters.push(check);
      });
    },
    get size() { return items.length; },
    get idle() { return !running && items.length === 0; },
    async drain() {
      while (!this.idle) await new Promise((r) => setTimeout(r, 5));
    },
  };
}

