export class QueryBuilder {
  private clauses: string[] = [];
  private values: unknown[] = [];
  private order = '';
  private lim = '';

  constructor(private table: string) {}

  where(column: string, op: '=' | '>' | '<' | '>=' | '<=' | 'LIKE', value: unknown) {
