  }

  limit(n: number) {
    this.lim = ` LIMIT ${Math.max(0, Math.floor(n))}`;
    return this;
  }

  build(): BuiltQuery {
    const where = this.clauses.length ? ` WHERE ${this.clauses.join(' AND ')}` : '';
