export function parseCsv(text: string, options?: { delimiter?: string }): ParseCsvResult {
  const delim = options?.delimiter ?? ',';
  const rows: string[][] = [];
  let row: string[] = [];
  let field = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else inQuotes = false;
      } else field += c;
    } else if (c === '"') inQuotes = true;
    else if (c === delim) { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some((f) => f.length > 0)) rows.push(row);
      row = [];
    } else field += c;
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }

  const [headers, ...data] = rows;
  return { headers: headers ?? [], rows: data.map((r) => Object.fromEntries(headers.map((h, i) => [h, r[i] ?? '']))) };
}

export function toCsv(headers: string[], rows: Array<Array<string | number | boolean | null>>): string {
  function esc(v: string | number | boolean | null): string {
    const s = v === null ? '' : String(v);
    return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  }
  const head = headers.map(esc).join(',');
  const body = rows.map((r) => r.map(esc).join(','));
  return [head, ...body].join('\n');
}

export function paginate<T>(items: T[], page: number, pageSize: number): Page<T> {
  const total = items.length;
  const totalPages = Math.max(1, Math.ceil(total / Math.max(1, pageSize)));
  const p = Math.max(0, Math.min(page, totalPages - 1));
  const start = p * pageSize;
  return {
    items: items.slice(start, start + pageSize),
    page: p,
    pageSize,
    total,
    totalPages,
    hasNext: p < totalPages - 1,
  };
}

export async function withTransaction<T>(
  begin: () => Promise<TxExecutor>,
  commit: () => Promise<void>,
  rollback: () => Promise<void>,
  fn: (tx: TxExecutor) => Promise<T>,
): Promise<T> {
  const tx = await begin();
  try {
    const result = await fn(tx);
    await commit();
    return result;
  } catch (e) {
    try { await rollback(); } catch { /* best effort */ }
    throw e;
  }
}

