export function quicksort<T>(items: T[], compare?: (a: T, b: T) => number): T[] {
  const arr = [...items];
  const cmp = compare ?? ((a: T, b: T) => (a < b ? -1 : a > b ? 1 : 0));

  function partition(lo: number, hi: number): number {
    const mid = (lo + hi) >> 1;
    const pivot = arr[mid];
    [arr[mid], arr[hi]] = [arr[hi], arr[mid]];
    let i = lo;
    for (let j = lo; j < hi; j++) {
      if (cmp(arr[j], pivot) < 0) { [arr[i], arr[j]] = [arr[j], arr[i]]; i++; }
    }
    [arr[i], arr[hi]] = [arr[hi], arr[i]];
    return i;
  }

  function sort(lo: number, hi: number) {
    if (lo >= hi) return;
    const p = partition(lo, hi);
    sort(lo, p - 1);
    sort(p + 1, hi);
  }

  sort(0, arr.length - 1);
  return arr;
}

export function mergesort<T>(items: T[], compare?: (a: T, b: T) => number): T[] {
  const cmp = compare ?? ((a: T, b: T) => (a < b ? -1 : a > b ? 1 : 0));

  function merge(left: T[], right: T[]): T[] {
    const out: T[] = [];
    let i = 0, j = 0;
    while (i < left.length && j < right.length) {
      if (cmp(left[i], right[j]) <= 0) out.push(left[i++]);
      else out.push(right[j++]);
    }
    return out.concat(left.slice(i), right.slice(j));
  }

  function sort(arr: T[]): T[] {
    if (arr.length <= 1) return arr;
    const mid = arr.length >> 1;
    return merge(sort(arr.slice(0, mid)), sort(arr.slice(mid)));
  }

  return sort([...items]);
}

export function createHeap<T>(compare?: (a: T, b: T) => number) {
  const arr: T[] = [];
  const cmp = compare ?? ((a: T, b: T) => (a < b ? -1 : a > b ? 1 : 0));

  function siftUp(i: number) {
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (cmp(arr[i], arr[parent]) >= 0) break;
      [arr[i], arr[parent]] = [arr[parent], arr[i]];
      i = parent;
    }
  }

  function siftDown(i: number) {
    const n = arr.length;
    while (true) {
      let smallest = i;
      const l = 2 * i + 1, r = 2 * i + 2;
      if (l < n && cmp(arr[l], arr[smallest]) < 0) smallest = l;
      if (r < n && cmp(arr[r], arr[smallest]) < 0) smallest = r;
      if (smallest === i) break;
      [arr[i], arr[smallest]] = [arr[smallest], arr[i]];
      i = smallest;
    }
  }

  return {
    push(value) { arr.push(value); siftUp(arr.length - 1); },
    pop() {
      if (arr.length === 0) return undefined;
      const top = arr[0];
      const last = arr.pop()!;
      if (arr.length > 0) { arr[0] = last; siftDown(0); }
      return top;
    },
    peek: () => arr[0],
    get size() { return arr.length; },
    get isEmpty() { return arr.length === 0; },
  };
}

