export function knapsack(items: KnapsackItem[], capacity: number) {
  const n = items.length;
  const dp: number[][] = Array.from({ length: n + 1 }, () => Array(capacity + 1).fill(0));

  for (let i = 1; i <= n; i++) {
    for (let w = 0; w <= capacity; w++) {
      if (items[i - 1].weight <= w) {
        dp[i][w] = Math.max(dp[i - 1][w], dp[i - 1][w - items[i - 1].weight] + items[i - 1].value);
      } else {
        dp[i][w] = dp[i - 1][w];
      }
    }
  }

  const ids: string[] = [];
  let w = capacity;
  for (let i = n; i > 0 && w > 0; i--) {
    if (dp[i][w] !== dp[i - 1][w]) {
      ids.unshift(items[i - 1].id);
      w -= items[i - 1].weight;
    }
  }

  const totalWeight = ids.reduce((s, id) => s + items.find((i) => i.id === id)!.weight, 0);
  return { ids, totalValue: dp[n][capacity], totalWeight };
}

export function solveNQueens(n: number): number[][] {
  const solutions: number[][] = [];
  const cols = new Set<number>();
  const diag1 = new Set<number>();
  const diag2 = new Set<number>();
  const board: number[] = [];

  function place(row: number) {
    if (row === n) { solutions.push([...board]); return; }
    for (let col = 0; col < n; col++) {
      if (cols.has(col) || diag1.has(row - col) || diag2.has(row + col)) continue;
      cols.add(col); diag1.add(row - col); diag2.add(row + col);
      board.push(col);
      place(row + 1);
      board.pop();
      cols.delete(col); diag1.delete(row - col); diag2.delete(row + col);
    }
  }

  place(0);
  return solutions;
}

export function wildcardToRegex(pattern: string): RegExp {
  const escaped = pattern
    .replace(/[.+^${}()|[\]\\]/g, '\\$&')
    .replace(/\*/g, '.*')
    .replace(/\?/g, '.');
  return new RegExp(`^${escaped}$`);
}

export function globMatch(pattern: string, text: string): boolean {
  return wildcardToRegex(pattern).test(text);
}

export function evaluateExpression(expr: string): number {
  const tokens = expr.replace(/\s+/g, '').match(/(\d+\.?\d*|[+\-*/()])/g);
  if (!tokens) throw new Error('invalid_expression');

  const output: string[] = [];
  const ops: string[] = [];
  const precedence: Record<string, number> = { '+': 1, '-': 1, '*': 2, '/': 2 };

  for (const t of tokens) {
    if (/\d/.test(t)) {
      output.push(t);
    } else if (t === '(') {
      ops.push(t);
    } else if (t === ')') {
      while (ops.length && ops[ops.length - 1] !== '(') output.push(ops.pop()!);
      ops.pop();
    } else {
      while (ops.length && precedence[ops[ops.length - 1]] >= precedence[t]) output.push(ops.pop()!);
      ops.push(t);
    }
  }
  while (ops.length) output.push(ops.pop()!);

  const stack: number[] = [];
  for (const t of output) {
    if (/\d/.test(t)) stack.push(Number(t));
    else {
      const b = stack.pop()!, a = stack.pop()!;
      if (t === '+') stack.push(a + b);
      if (t === '-') stack.push(a - b);
      if (t === '*') stack.push(a * b);
      if (t === '/') stack.push(a / b);
    }
  }
  return stack[0];
}

export function tokenize(source: string, rules: TokenRule[], skip: Set<string> = new Set(['ws'])): Token[] {
  const tokens: Token[] = [];
  let pos = 0;
  let safety = 0;

  while (pos < source.length && safety++ < 1_000_000) {
    let matched = false;
    for (const rule of rules) {
      rule.pattern.lastIndex = 0;
      const m = rule.pattern.exec(source.slice(pos));
      if (m && m.index === 0 && m[0].length > 0) {
        if (!skip.has(rule.type)) tokens.push({ type: rule.type, value: m[0], pos });
        pos += m[0].length;
        matched = true;
        break;
      }
    }
    if (!matched) throw new Error(`unexpected char at ${pos}: '${source[pos]}'`);
  }
  return tokens;
}

