    get ended() { return audio.ended; },
    onEnded(cb) { endedCbs.push(cb); return () => { const i = endedCbs.indexOf(cb); if (i >= 0) endedCbs.splice(i, 1); }; },
    destroy() { audio.pause(); audio.src = ''; endedCbs.length = 0; },
  };
}

