export function shouldSample(ratio: number, seed?: string) {
  if (ratio >= 1) return true;
  if (ratio <= 0) return false;
  if (seed) {
    let h = 2166136261;
    for (let i = 0; i < seed.length; i++) { h ^= seed.charCodeAt(i); h = Math.imul(h, 16777619); }
