  }
  get x() { return this._x; }
  get y() { return this._y; }
  get zoom() { return this._zoom; }
  setZoom(z: number) { this._zoom = Math.min(this.opts.maxZoom ?? 4, Math.max(this.opts.minZoom ?? 0.2, z)); }
}

