  const p: Quat = { x: v.x, y: v.y, z: v.z, w: 0 };
  const conj = { x: -q.x, y: -q.y, z: -q.z, w: q.w };
  const r = qMul(qMul(q, p), conj);
  return { x: r.x, y: r.y, z: r.z };
}

