export function ternaryMax(f: (x: number) => number, lo: number, hi: number, tol = 1e-9) {
  let l = lo, h = hi;
  while (h - l > tol) {
    const m1 = l + (h - l) / 3, m2 = h - (h - l) / 3;
    if (f(m1) < f(m2)) l = m1; else h = m2;
  }
  const x = (l + h) / 2;
  return { x, value: f(x) };
}

function det2(m: number[][]) { return m[0][0] * m[1][1] - m[0][1] * m[1][0]; }
export function solve2x2(a: number[][], b: number[]) {
  const d = det2(a);
  if (Math.abs(d) < 1e-12) return null;
  const x = (b[0] * a[1][1] - a[0][1] * b[1]) / d;
  const y = (a[0][0] * b[1] - b[0] * a[1][0]) / d;
  return [x, y];
}
export function solve3x3(a: number[][], b: number[]) {
  const det = (m: number[][]) =>
    m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1]) - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0]) + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);
  const d = det(a);
  if (Math.abs(d) < 1e-12) return null;
  const col = (i: number) => a.map((row, r) => (row[i] = b[r], row));
  return [0, 1, 2].map((i) => {
    const m = a.map((row) => row.slice());
    for (let r = 0; r < 3; r++) m[r][i] = b[r];
    return det(m) / d;
  });
}

