export function heapsort<T>(arr: T[], less: (a: T, b: T) => boolean = (a, b) => a < b) {
  const a = arr.slice();
  const n = a.length;
  const sift = (i: number, size: number) => {
    while (true) {
      let largest = i, l = 2 * i + 1, r = 2 * i + 2;
      if (l < size && less(a[largest], a[l])) largest = l;
      if (r < size && less(a[largest], a[r])) largest = r;
      if (largest === i) return;
      [a[i], a[largest]] = [a[largest], a[i]];
      i = largest;
    }
  };
  for (let i = (n >> 1) - 1; i >= 0; i--) sift(i, n);
  for (let end = n - 1; end > 0; end--) {
    [a[0], a[end]] = [a[end], a[0]];
    sift(0, end);
  }
  return a;
}

export function radixSort(nums: number[]) {
  if (nums.length === 0) return [];
  const max = Math.max(...nums);
  const buckets: number[][] = Array.from({ length: 10 }, () => []);
  let exp = 1;
  while (exp <= max) {
    buckets.forEach((b) => b.length = 0);
    for (const x of nums) buckets[Math.floor(x / exp) % 10].push(x);
    let i = 0;
    for (const b of buckets) for (const x of b) nums[i++] = x;
    exp *= 10;
  }
  return nums;
}

