export class PrefixSum2D {
  private ps: number[][];
  constructor(grid: number[][]) {
    const h = grid.length, w = grid[0]?.length ?? 0;
    this.ps = Array.from({ length: h + 1 }, () => new Array(w + 1).fill(0));
