export function mergeIntervals(intervals: Interval[]) {
  if (!intervals.length) return [];
  const sorted = intervals.slice().sort((a, b) => a.start - b.start);
  const out: Interval[] = [sorted[0]];
  for (const iv of sorted.slice(1)) {
    const last = out[out.length - 1];
    if (iv.start <= last.end) last.end = Math.max(last.end, iv.end);
    else out.push({ ...iv });
  }
  return out;
}

export function sortedInsert<T>(arr: T[], value: T, compare: (a: T, b: T) => number = (a, b) => (a < b ? -1 : a > b ? 1 : 0)) {
  let lo = 0, hi = arr.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    const c = compare(value, arr[mid]);
    if (c === 0) return false;
    if (c < 0) hi = mid; else lo = mid + 1;
  }
  arr.splice(lo, 0, value);
  return true;
}

