export function pluralCategory(locale: string, count: number) {
  try { return new Intl.PluralRules(locale).select(count); }
  catch { return count === 1 ? 'one' : 'other'; }
}
export function pickPlural(locale: string, count: number, forms: Record<string, string>) {
  const cat = pluralCategory(locale, count);
  return forms[cat] ?? forms.other ?? forms.one ?? String(count);
}

const cache = new Map<string, Intl.Collator>();
export function localeCompareFn(locale: string, opts: Intl.CollatorOptions = {}) {
  const key = locale + JSON.stringify(opts);
  if (!cache.has(key)) cache.set(key, new Intl.Collator(locale, opts));
  return (a: string, b: string) => cache.get(key)!.compare(a, b);
}

const cache = new Map<string, Intl.NumberFormat>();
export function formatNumber(locale: string, value: number, opts: Intl.NumberFormatOptions = {}) {
  const key = locale + JSON.stringify(opts);
  if (!cache.has(key)) cache.set(key, new Intl.NumberFormat(locale, opts));
  return cache.get(key)!.format(value);
}

export function formatCurrency(locale: string, value: number, currency: string, opts: Intl.NumberFormatOptions = {}) {
  return formatNumber(locale, value, { style: 'currency', currency, ...opts });
}

const cache = new Map<string, Intl.DateTimeFormat>();
export function formatDate(locale: string, date: Date | number, opts: Intl.DateTimeFormatOptions = { dateStyle: 'medium' }) {
  const key = locale + JSON.stringify(opts);
  if (!cache.has(key)) cache.set(key, new Intl.DateTimeFormat(locale, opts));
  return cache.get(key)!.format(new Date(date));
}

const cache = new Map<string, Intl.RelativeTimeFormat>();
const UNITS: Array<[Intl.RelativeTimeFormatUnit, number]> = [
  ['year', 31536000000], ['month', 2592000000], ['week', 604800000],
  ['day', 86400000], ['hour', 3600000], ['minute', 60000], ['second', 1000],
];
export function relativeTime(locale: string, deltaMs: number, opts: Intl.RelativeTimeFormatOptions = { numeric: 'auto' }) {
  const key = locale + JSON.stringify(opts);
  if (!cache.has(key)) cache.set(key, new Intl.RelativeTimeFormat(locale, opts));
  for (const [unit, size] of UNITS) {
    const value = Math.round(deltaMs / size);
    if (Math.abs(value) >= 1 || unit === 'second') return cache.get(key)!.format(value, unit);
  }
  return cache.get(key)!.format(0, 'second');
}

const RTL = /^(ar|fa|he|ur|yi|dv|ps|sd|ckb|az-Arab|ku-Arab|ug)/i;
export function isRtlLocale(locale: string) { return RTL.test(locale); }
export function dirForLocale(locale: string) { return isRtlLocale(locale) ? 'rtl' : 'ltr'; }

const RTL_RE = /[\u0590-\u08FF\uFB1D-\uFDFD\uFE70-\uFEFC]/;
export function bidiGrouped(text: string) {
  const out: string[] = [];
  let buf = '', dir: 'rtl' | 'ltr' | '' = '';
  for (const ch of text) {
    const d = RTL_RE.test(ch) ? 'rtl' : /[a-zA-Z0-9]/.test(ch) ? 'ltr' : '';
    if (d && d !== dir) { if (buf) out.push(buf); buf = ''; dir = d; }
    buf += ch;
  }
  if (buf) out.push(buf);
  return out;
}

export function localeSort(items: string[], locale: string, desc = false) {
  const cmp = localeCompareFn(locale);
  return items.slice().sort((a, b) => (desc ? -1 : 1) * cmp(a, b));
}

export function formatMessage(template: string, params: Record<string, string | number>) {
  return template.replace(/\{(\w+)\}/g, (_, key) => (params[key] !== undefined ? String(params[key]) : `{${key}}`));
}

export function resolveKey(messages: Record<string, Record<string, string>>, locale: string, key: string, fallback = 'en') {
  const lang = locale.split('-')[0];
  for (const cand of [locale, lang, fallback]) {
    const hit = messages[cand]?.[key];
    if (hit !== undefined) return hit;
  }
  return key;
}

export function negotiateLocale(acceptLanguage: string, supported: string[], defaultLocale: string) {
  const parsed = acceptLanguage.split(',').map((p) => {
    const [tag, ...params] = p.trim().split(';');
    const q = parseFloat(params.find((x) => x.trim().startsWith('q='))?.split('=')[1] ?? '1');
    return { tag: tag.trim(), q: isNaN(q) ? 0 : q };
  }).sort((a, b) => b.q - a.q);
  for (const { tag } of parsed) {
    const exact = supported.find((s) => s.toLowerCase() === tag.toLowerCase());
    if (exact) return exact;
    const lang = tag.split('-')[0].toLowerCase();
    const partial = supported.find((s) => s.split('-')[0].toLowerCase() === lang);
    if (partial) return partial;
  }
  return defaultLocale;
}

export function resolveDefaultLocale(fallback = 'en') {
  if (typeof navigator !== 'undefined' && navigator.languages?.length) return navigator.languages[0];
  if (typeof Intl !== 'undefined' && Intl.DateTimeFormat().resolvedOptions().locale) return Intl.DateTimeFormat().resolvedOptions().locale;
  return fallback;
}

export function formatCompact(locale: string, value: number, maxFractionDigits = 1) {
  return formatNumber(locale, value, { notation: 'compact', maximumFractionDigits: maxFractionDigits });
}

export function ordinalSuffix(locale: string, n: number) {
  const cat = new Intl.PluralRules(locale, { type: 'ordinal' }).select(n);
  const map: Record<string, string> = { one: 'st', two: 'nd', few: 'rd', other: 'th' };
  return map[cat] ?? 'th';
}

const MON = /^(en-US|en-CA|ja|zh|ko|pt-BR|es|ar|he)/i;
const SAT = /^(ar-DZ|ar-EG|af|bn|hi|ur|dv)/i;
export function weekStartDay(locale: string) {
  if (SAT.test(locale)) return 6;
  if (MON.test(locale)) return 0;
  return 1;
}

export function graphemes(text: string, locale = 'en') {
  if (typeof Intl.Segmenter !== 'undefined') {
    const seg = new Intl.Segmenter(locale, { granularity: 'grapheme' });
    return [...seg.segment(text)].map((s) => s.segment);
  }
  return Array.from(text); // fallback: code-point split
}

export function safeSlice(text: string, start: number, end?: number) {
  const chars = Array.from(text);
  return chars.slice(start, end).join('');
}

const RTL_RE = /[\u0590-\u08FF\uFB1D-\uFDFD\uFE70-\uFEFC]/;
const LTR_RE = /[A-Za-z0-9\u00C0-\u02AF\u0370-\u03FF\u0400-\u04FF\u0530-\u058F\u0600-\u06FF\u0E00-\u0E7F]/;
export function charDirection(ch: string): Dir {
  if (RTL_RE.test(ch)) return 'rtl';
  if (LTR_RE.test(ch)) return 'ltr';
  return 'neutral';
}

export function formatUnit(locale: string, value: number, unit: string) {
  return formatNumber(locale, value, { style: 'unit', unit: unit as Intl.NumberFormatOptions['unit'] });
}

export function formatPercent(locale: string, ratio: number, maxFractionDigits = 1) {
  return formatNumber(locale, ratio, { style: 'percent', maximumFractionDigits: maxFractionDigits });
}

export function calendarOf(locale: string) {
  try { return new Intl.DateTimeFormat(locale).resolvedOptions().calendar; }
  catch { return 'gregory'; }
}

export function listTimezones() {
  try {
    const supported = (Intl as unknown as { supportedValuesOf?: (k: string) => string[] }).supportedValuesOf?.('timeZone');
    if (supported?.length) return supported;
  } catch { /* fall through */ }
  return ['UTC', 'America/New_York', 'Europe/London', 'Asia/Tokyo', 'Australia/Sydney'];
}

export function interpolate(template: string, locale: string, params: Record<string, unknown>) {
  return template.replace(/\{(\w+)(?:,(\w+)(?:,([^}]+))?)?\}/g, (_, key, kind, opt) => {
    const v = params[key];
    if (v === undefined) return `{${key}}`;
    if (kind === 'number') return formatNumber(locale, Number(v), opt ? JSON.parse(`{${opt}}`) : {});
    if (kind === 'date') return formatDate(locale, new Date(Number(v)), { dateStyle: 'medium' });
    return String(v);
  });
}

export function groupDigits(locale: string, value: number) {
  return formatNumber(locale, value, { useGrouping: true });
}

export function annuityFutureValue(deposit: number, ratePerPeriod: number, periods: number) {
  if (ratePerPeriod === 0) return deposit * periods;
  const g = Math.pow(1 + ratePerPeriod, periods);
  return deposit * ((g - 1) / ratePerPeriod);
}

export function presentValue(future: number, ratePerPeriod: number, periods: number) {
  return future / Math.pow(1 + ratePerPeriod, periods);
}

export function netPresentValue(cashFlows: number[], rate: number) {
  return cashFlows.reduce((sum, cf, t) => sum + cf / Math.pow(1 + rate, t), 0);
}

function npvAt(cashFlows: number[], r: number) {
  return cashFlows.reduce((s, cf, t) => s + cf / Math.pow(1 + r, t), 0);
}
export function irr(cashFlows: number[], guess = 0.1, maxIter = 100) {
  let lo = -0.9999, hi = 10, r = guess;
  for (let i = 0; i < maxIter; i++) {
    const f = npvAt(cashFlows, r);
    if (Math.abs(f) < 1e-8) break;
    if (f > 0) { lo = r; r = (r + hi) / 2; }
    else { hi = r; r = (lo + r) / 2; }
  }
  return r;
}

export function amortization(principal: number, annualRate: number, years: number, paymentsPerYear = 12) {
  const n = years * paymentsPerYear;
  const r = annualRate / paymentsPerYear;
  const payment = r === 0 ? principal / n : (principal * r) / (1 - Math.pow(1 + r, -n));
  const rows: AmortRow[] = [];
  let balance = principal;
  for (let period = 1; period <= n; period++) {
    const interest = balance * r;
    const principalPart = payment - interest;
    balance -= principalPart;
    rows.push({ period, payment, principal: principalPart, interest, balance: Math.max(0, balance) });
  }
  return rows;
}

export function compoundInterest(principal: number, annualRate: number, timesPerYear: number, years: number) {
  return principal * Math.pow(1 + annualRate / timesPerYear, timesPerYear * years);
}

export function simpleInterest(principal: number, annualRate: number, years: number) {
  const interest = principal * annualRate * years;
  return { interest, total: principal + interest };
}

export function capm(riskFree: number, beta: number, marketReturn: number) {
  return riskFree + beta * (marketReturn - riskFree);
}

export function dollarCostAverage(periodicAmount: number, prices: number[]) {
  let shares = 0, spent = 0;
  for (const price of prices) {
    if (price <= 0) continue;
    shares += periodicAmount / price;
    spent += periodicAmount;
  }
  return { shares, totalSpent: spent, avgCost: spent / (shares || 1) };
}

export function vwap(bars: Array<{ high: number; low: number; close: number; volume: number }>) {
  let pv = 0, vol = 0;
  for (const b of bars) {
    const tp = (b.high + b.low + b.close) / 3;
    pv += tp * b.volume;
    vol += b.volume;
  }
  return vol === 0 ? 0 : pv / vol;
}

export function returnPct(start: number, end: number) {
  return start === 0 ? 0 : (end - start) / start;
}
export function cagr(start: number, end: number, years: number) {
  if (start <= 0 || years <= 0) return 0;
  return Math.pow(end / start, 1 / years) - 1;
}

export function allocate(total: number, weights: Record<string, number>) {
  const out: Record<string, number> = {};
  for (const [name, w] of Object.entries(weights)) out[name] = total * w;
  return out;
}

export function rebalanceTrades(current: Record<string, number>, weights: Record<string, number>, total: number) {
  const out: Record<string, number> = {};
  for (const name of Object.keys(weights)) {
    const targetValue = total * weights[name];
    out[name] = targetValue - (current[name] ?? 0);
  }
  return out;
}

export function taxBracketTax(income: number, brackets: TaxBracket[]) {
  let tax = 0, prev = 0;
  for (const b of brackets) {
    const slice = Math.min(income, b.upTo) - prev;
    if (slice <= 0) break;
    tax += slice * b.rate;
    prev = b.upTo;
  }
  return tax;
}

export function formatMoney(amount: number, symbol = '$', decimals = 2) {
  const sign = amount < 0 ? '-' : '';
  const v = Math.abs(amount);
  const fixed = v.toFixed(decimals);
  const [int, frac] = fixed.split('.');
  const grouped = int.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return sign + symbol + grouped + (frac ? '.' + frac : '');
}

export function budgetByCategory(txs: BudgetTx[], budgets: Record<string, number>) {
  const spent = new Map<string, number>();
  for (const t of txs) spent.set(t.category, (spent.get(t.category) ?? 0) + t.amount);
  const out: Record<string, { spent: number; budget: number; remaining: number }> = {};
  for (const cat of new Set([...spent.keys(), ...Object.keys(budgets)])) {
    const s = spent.get(cat) ?? 0;
    const b = budgets[cat] ?? 0;
    out[cat] = { spent: s, budget: b, remaining: b - s };
  }
  return out;
}

export function envelopeAllocate(income: number, envelopes: Record<string, number>) {
  const totalPct = Object.values(envelopes).reduce((s, p) => s + p, 0);
  if (totalPct > 1.0001) throw new Error('Envelope percentages exceed 100%');
  const out: Record<string, number> = {};
  for (const [name, pct] of Object.entries(envelopes)) out[name] = income * pct;
  return out;
}

export function upcomingDues(bills: Array<{ name: string; day: number; amount: number }>, from: Date, months: number) {
  const out: Array<{ name: string; date: Date; amount: number }> = [];
  for (let m = 0; m < months; m++) {
    for (const b of bills) {
      const date = new Date(from.getFullYear(), from.getMonth() + m, Math.min(b.day, 28));
      if (date >= from) out.push({ name: b.name, date, amount: b.amount });
    }
  }
  return out.sort((a, b) => a.date.getTime() - b.date.getTime());
}

export function savingsProgress(saved: number, target: number, monthly: number) {
  const percent = target <= 0 ? 100 : Math.min(100, (saved / target) * 100);
  const monthsToGoal = monthly <= 0 || saved >= target ? null : Math.ceil((target - saved) / monthly);
  return { percent, monthsToGoal };
}

export function debtSnowball(debts: Array<{ name: string; balance: number; rate: number }>) {
  return [...debts]
    .sort((a, b) => a.balance - b.balance)
    .map((d, i) => ({ ...d, payoffOrder: i + 1 }));
}

export function debtAvalanche(debts: Array<{ name: string; balance: number; rate: number }>) {
  return [...debts]
    .sort((a, b) => b.rate - a.rate)
    .map((d, i) => ({ ...d, payoffOrder: i + 1 }));
}

export function invoiceAging(invoices: Array<{ dueDate: Date; amount: number }>, now: Date) {
  const out: InvoiceAging = { current: 0, d30: 0, d60: 0, d90: 0, over90: 0 };
  for (const inv of invoices) {
    const days = Math.floor((now.getTime() - inv.dueDate.getTime()) / 86400000);
    if (days <= 0) out.current += inv.amount;
    else if (days <= 30) out.d30 += inv.amount;
    else if (days <= 60) out.d60 += inv.amount;
    else if (days <= 90) out.d90 += inv.amount;
    else out.over90 += inv.amount;
  }
  return out;
}

export function expenseTrend(last: Record<string, number>, now: Record<string, number>) {
  const cats = new Set([...Object.keys(last), ...Object.keys(now)]);
  const out: Record<string, { last: number; now: number; delta: number; pct: number }> = {};
  for (const c of cats) {
    const l = last[c] ?? 0, n = now[c] ?? 0;
    out[c] = { last: l, now: n, delta: n - l, pct: l === 0 ? 0 : (n - l) / l };
  }
  return out;
}

export function splitPayment(balance: number, annualRate: number, payment: number, periodsPerYear = 12) {
  const interest = balance * (annualRate / periodsPerYear);
  const principal = Math.min(payment, balance + interest) - interest;
  return { interest, principal: Math.max(0, principal), newBalance: Math.max(0, balance - principal) };
}

export function billSplit(amount: number, tipPercent: number, people: number, taxPercent = 0) {
  const tax = amount * (taxPercent / 100);
  const tip = (amount + tax) * (tipPercent / 100);
  const total = amount + tax + tip;
  return { subtotal: amount, tip, total, perPerson: people <= 0 ? total : total / people };
}

export function letterGrade(pct: number, boundaries: Record<string, number> = { A: 90, B: 80, C: 70, D: 60 }) {
  const entries = Object.entries(boundaries).sort((a, b) => b[1] - a[1]);
  for (const [grade, min] of entries) if (pct >= min) return grade;
  return 'F';
}

export function curveScores(scores: number[], targetMean: number) {
  const mean = scores.reduce((s, x) => s + x, 0) / (scores.length || 1);
  const shift = targetMean - mean;
  return scores.map((s) => Math.min(100, Math.max(0, s + shift)));
}

export function gpa(courses: Array<{ credits: number; points: number }>) {
  const totalCredits = courses.reduce((s, c) => s + c.credits, 0);
  if (totalCredits === 0) return 0;
  return courses.reduce((s, c) => s + c.credits * c.points, 0) / totalCredits;
}

export function sm2(quality: number, interval: number, easiness: number, repetitions: number, now: Date) {
  const q = Math.max(0, Math.min(5, quality));
  let ef = easiness + (0.1 - (5 - q) * (0.08 + (5 - q) * 0.02));
  if (ef < 1.3) ef = 1.3;
  if (q < 3) return { interval: 1, easiness: ef, repetitions: 0, due: new Date(now.getTime() + 86400000) };
  const next = repetitions === 0 ? 1 : repetitions === 1 ? 6 : Math.round(interval * ef);
  return { interval: next, easiness: ef, repetitions: repetitions + 1, due: new Date(now.getTime() + next * 86400000) };
}

export function retentionAt(hoursElapsed: number, strength = 1) {
  return Math.exp(-hoursElapsed / (strength * 24));
}

export function shuffleQuestions<T>(questions: T[], seed: number) {
  const rand = () => {
    seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const arr = questions.slice();
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

export function normalizeScore(raw: number, max: number, min = 0) {
  if (max === min) return 100;
  return Math.round(((raw - min) / (max - min)) * 100);
}

export function courseProgress(done: number, total: number) {
  return { percent: total <= 0 ? 0 : (done / total) * 100, completed: done, remaining: Math.max(0, total - done) };
}

export function streak(dates: Date[], today: Date) {
  const key = (d: Date) => `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
  const set = new Set(dates.map(key));
  let current = 0, longest = 0, run = 0;
  const cursor = new Date(today);
  while (set.has(key(cursor))) { current++; cursor.setDate(cursor.getDate() - 1); }
  const sorted = [...set].sort();
  let prev: string | null = null;
  for (const k of sorted) {
    if (prev) {
      const [py, pm, pd] = prev.split('-').map(Number);
      const [cy, cm, cd] = k.split('-').map(Number);
      const diff = (new Date(cy, cm, cd).getTime() - new Date(py, pm, pd).getTime()) / 86400000;
      run = diff === 1 ? run + 1 : 1;
    } else run = 1;
    longest = Math.max(longest, run);
    prev = k;
  }
  return { current, longest };
}

export function passing(score: number, cutoff = 60) {
  return { pass: score >= cutoff, margin: score - cutoff };
}

export function scoreMultipleChoice(answers: string[], key: string[], partialCredit = false) {
  let score = 0;
  const wrong: number[] = [];
  answers.forEach((a, i) => {
    if (a === key[i]) score++;
    else if (partialCredit && a) score += 0.5;
    else wrong.push(i);
  });
  const total = key.length;
  return { correct: Math.round(score), total, percent: total === 0 ? 0 : (score / total) * 100, wrong };
}

export function clozeMatches(input: string, expected: string, aliases: string[] = []) {
  const norm = (s: string) => s.trim().toLowerCase().replace(/\s+/g, ' ');
  return [expected, ...aliases].some((e) => norm(e) === norm(input));
}

export function sessionStats(durationsMin: number[]) {
  const total = durationsMin.reduce((s, d) => s + d, 0);
  return { sessions: durationsMin.length, totalMinutes: total, avgMinutes: durationsMin.length ? total / durationsMin.length : 0 };
}

export function confidencePlan(rating: number) {
  if (rating <= 2) return { bucket: 'relearn', priority: 4 };
  if (rating === 3) return { bucket: 'review', priority: 3 };
  if (rating === 4) return { bucket: 'reinforce', priority: 2 };
  return { bucket: 'mastered', priority: 1 };
}

export function vocabList(words: string[]) {
  const unique = [...new Set(words.map((w) => w.trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  return { words: unique, count: unique.length };
}

export function quizPace(startedAt: number, durationMs: number, done: number, total: number, now: number) {
  const remainingMs = Math.max(0, startedAt + durationMs - now);
  const remainingQs = Math.max(0, total - done);
  return { remainingMs, perQuestion: remainingQs === 0 ? 0 : remainingMs / remainingQs };
}

export function answerFeedback(correct: boolean, answer: string) {
  return correct
    ? { correct, text: `Correct! The answer is ${answer}.` }
    : { correct, text: `Not quite — the answer is ${answer}. Review and try again.` };
}

export function studyPlan(topics: string[], days: number) {
  const plan: string[][] = Array.from({ length: days }, () => []);
  topics.forEach((t, i) => plan[i % days].push(t));
  return plan.filter((d) => d.length);
}

export function masteryLevel(scores: number[]) {
  if (!scores.length) return { level: 'untested', avg: 0, next: 'Take a first assessment' };
  const avg = scores.reduce((s, x) => s + x, 0) / scores.length;
  if (avg >= 90) return { level: 'mastered', avg, next: 'Challenge with advanced topics' };
  if (avg >= 75) return { level: 'proficient', avg, next: 'Reinforce with mixed practice' };
  if (avg >= 60) return { level: 'developing', avg, next: 'Review missed concepts' };
  return { level: 'beginning', avg, next: 'Restart with foundational lessons' };
}

export function dueCards(cards: Card[], now: Date) {
  const due = cards.filter((c) => c.due.getTime() <= now.getTime());
  return { due, notDue: cards.length - due.length };
}

export function fleschReadingEase(words: number, sentences: number, syllables: number) {
  if (!words || !sentences) return 0;
  return Math.max(0, Math.min(100, 206.835 - 1.015 * (words / sentences) - 84.6 * (syllables / words)));
}

export function badgesEarned(stats: Record<string, number>, milestones: Record<string, number>) {
  const earned: string[] = [], locked: string[] = [];
  for (const [badge, need] of Object.entries(milestones)) (stats[badge] ?? 0) >= need ? earned.push(badge) : locked.push(badge);
  return { earned, locked };
}

export function countSyllables(word: string) {
  const w = word.toLowerCase().replace(/[^a-z]/g, '');
  if (!w) return 0;
  let count = (w.match(/[aeiouy]+/g) ?? []).length;
  if (w.endsWith('e') && !/le$/.test(w) && count > 1) count--;
  return Math.max(1, count);
}

export function unlockedLessons(passedCount: number, total: number) {
  return Array.from({ length: total }, (_, i) => ({ index: i, unlocked: i <= passedCount }));
}

export function mixReview<T>(due: T[], fresh: T[], dailyNewCap: number) {
  const out: T[] = [];
  const d = due.slice(), f = fresh.slice(0, dailyNewCap);
  while (d.length || f.length) {
    if (d.length) out.push(d.shift()!);
    if (f.length) out.push(f.shift()!);
  }
  return out;
}

export function toCamelCase(input: string) {
