  const out: Array<{ type: '+' | '-' | ' '; line: string }> = [];
  let i = 0, j = 0;
  while (i < m && j < n) {
    if (A[i] === B[j]) { out.push({ type: ' ', line: A[i] }); i++; j++; }
    else if (dp[i + 1][j] >= dp[i][j + 1]) { out.push({ type: '-', line: A[i] }); i++; }
    else { out.push({ type: '+', line: B[j] }); j++; }
