      const dx = out[j].x + out[j].w / 2 - (out[i].x + out[i].w / 2);
      const dy = out[j].y + out[j].h / 2 - (out[i].y + out[i].h / 2);
      const ax = Math.abs(dx) < Math.abs(dy) ? 0 : Math.sign(dx || 1);
