  constructor(private process: (job: T) => void) {}
  enqueue(job: T) {
    this.q.push(job);
    if (!this.running) { this.running = true; this.drain(); }
  }
  private drain() {
    const job = this.q.shift();
    if (!job) { this.running = false; return; }
    this.process(job);
