export function createCanvas(width: number, height: number): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  return canvas;
}

export function render(canvas: HTMLCanvasElement, ctx: CanvasRenderingContext2D, state: { player: { x: number; y: number }; enemies: { x: number; y: number }[]; cheese: { x: number; y: number } }) {
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(state.cheese.x, state.cheese.y, 10, 0, Math.PI * 2);
  ctx.fill();
  state.enemies.forEach((enemy) => {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, 10, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.beginPath();
  ctx.arc(state.player.x, state.player.y, 10, 0, Math.PI * 2);
  ctx.fill();
}

export function getKeyDown(key: string): boolean {
  const keys = Object.keys(window.__keyStates || {});
  return keys.includes(key.toLowerCase());
}

export class Scene {
  private entities: { update: (dt: number) => void; render: () => void }[] = [];

  constructor(private canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.canvas.width = 800;
    this.canvas.height = 600;
  }

  addEntity(entity: { update: (dt: number) => void; render: () => void }) {
    this.entities.push(entity);
  }

  update(dt: number) {
    this.entities.forEach((e) => e.update(dt));
  }

  render() {
    const ctx = this.canvas.getContext('2d');
    if (!ctx) return;
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
    this.entities.forEach((e) => e.render());
  }
}

export class Cheese {
