    this.velocity = { x: 0, y: 0, z: 0 };
  }
  update(dt: number) {
    this.velocity.y -= 0.05 * dt;
    this.position.x += this.velocity.x * dt;
    this.position.y += this.velocity.y * dt;
    this.position.z += this.velocity.z * dt;
  }
  render(renderer: any) {
    renderer.renderCheese(this.position);
  }
}

export class Enemy {
  position: { x: number; y: number };
  velocity: { x: number; y: number };
  target: { x: number; y: number };
  speed: number;

  constructor() {
    this.position = { x: 0, y: 0 };
    this.velocity = { x: 0, y: 0 };
    this.target = { x: 0, y: 0 };
    this.speed = 0.5;
  }

  update(playerPosition: { x: number; y: number }) {
    this.target = playerPosition;
    const dx = this.target.x - this.position.x;
    const dy = this.target.y - this.position.y;
    const distance = Math.hypot(dx, dy);
    this.velocity = { x: dx / distance * this.speed, y: dy / distance * this.speed };
    this.position.x += this.velocity.x;
    this.position.y += this.velocity.y;
  }

  render(canvasContext: CanvasRenderingContext2D) {
    canvasContext.fillStyle = 'red';
    canvasContext.fillRect(this.position.x, this.position.y, 20, 20);
  }
}

export class Item {
  private position: { x: number; y: number; z: number };
  private scale: { x: number; y: number; z: number };
  private color: string;
  private picked: boolean;

  constructor(x: number, y: number, z: number) {
    this.position = { x, y, z };
    this.scale = { x: 0.5, y: 0.5, z: 0.5 };
    this.color = '#ffd700';
    this.picked = false;
  }

  public update(dt: number) {}

  public render(renderer: import('three').Renderer) {
    const geometry = new import('three').SphereGeometry(this.scale.x, this.scale.y, this.scale.z);
    const material = new import('three').MeshBasicMaterial({ color: this.color });
    const mesh = new import('three').Mesh(geometry, material);
    mesh.position.set(this.position.x, this.position.y, this.position.z);
    renderer.scene.add(mesh);
  }

  public onPick() {
    this.picked = true;
  }

  public isPicked() {
    return this.picked;
  }
}

