#define COUNT 12

typedef struct {
    int current, next;
} Fibonacci;

void fibonacci_init(Fibonacci *f) { f->current = 0; f->next = 1; }
int fibonacci_next(Fibonacci *f) {
    int temp = f->current + f->next;
    f->current = f->next;
    f->next = temp;
    return temp;
}

int main(int argc, char **argv) {
    Fibonacci fib;
fibonacci_init(&fib);
printf("%d", fib.current);
for (int i = 1; i < COUNT; ++i) {
printf(" %d", fibonacci_next(&fib));
}
puts("");return 0;
