public class FibonacciService
{
    public int[] GenerateFibonacci(int count)
    {
        if (count <= 0) return new int[0];
        int[] fib = new int[count];
        fib[0] = 0;
        if (count == 1) return fib;
        fib[1] = 1;
        for (int i = 2; i < count; i++)
            fib[i] = fib[i - 1] + fib[i - 2];
        return fib;
    }
}

