export interface Note {
    id: number;
    title: string;
    content: string;
    createdAt: Date;
}

export class NoteService {
    private notes: Note[] = [];

    create(title: string, content: string): Note {
        const note = { id: this.notes.length + 1, title, content, createdAt: new Date() };
        this.notes.push(note);
        return note;
    }

    read(id: number): Note | undefined {
        return this.notes.find(n => n.id === id);
    }

    update(id: number, title: string, content: string): boolean {
        const note = this.notes.find(n => n.id === id);
        if (note) {
            note.title = title;
            note.content = content;
            return true;
        }
        return false;
    }

    delete(id: number): boolean {
        const index = this.notes.findIndex(n => n.id === id);
        if (index !== -1) {
            this.notes.splice(index, 1);
            return true;
        }
        return false;
    }
}

import { Note } from './models';

interface NoteService {
    createNote(title: string, content: string): Promise<Note>;
    updateNote(id: string, title?: string, content?: string): Promise<Note | null>;
    deleteNote(id: string): Promise<void>;
    getNote(id: string): Promise<Note | null>;
    getAllNotes(): Promise<Note[]>;
}

class NoteService {
    private notes: Note[] = [];

    createNote(title: string, content: string): Promise<Note> {
        const id = this.notes.length.toString();
        const note = { id, title, content, createdAt: new Date().toISOString() };
        this.notes.push(note);
        return Promise.resolve(note);
    }

    updateNote(id: string, title?: string, content?: string): Promise<Note | null> {
        const index = this.notes.findIndex(n => n.id === id);
        if (index === -1) return Promise.resolve(null);
        const updated = { ...this.notes[index], title, content, updatedAt: new Date().toISOString() };
        this.notes[index] = updated;
        return Promise.resolve(updated);
    }

    deleteNote(id: string): Promise<void> {
        this.notes = this.notes.filter(n => n.id !== id);
        return Promise.resolve();
    }

    getNote(id: string): Promise<Note | null> {
        return Promise.resolve(this.notes.find(n => n.id === id) || null);
    }

    getAllNotes(): Promise<Note[]> {
        return Promise.resolve([...this.notes]);
    }
}

import { NoteService } from './services';
import { Note } from './models';

const noteService = new NoteService();

export async function startAPI() {
  const app = require('express')();

  app.use(require('express')().json());

  app.post('/notes', async (req, res) => {
    try {
      const newNote = await noteService.create(req.body);
      res.status(201).json(newNote);
    } catch (error) {
      res.status(400).send(error.message);
    }
  });

  app.get('/notes', async (req, res) => {
    try {
      const notes = await noteService.getAll();
      res.status(200).json(notes);
    } catch (error) {
      res.status(500).send(error.message);
    }
  });

  app.get('/notes/:id', async (req, res) => {
    try {
      const note = await noteService.get(req.params.id);
      if (!note) return res.status(404).send('Note not found');
      res.status(200).json(note);
    } catch (error) {
      res.status(500).send(error.message);
    }
  });

  app.put('/notes/:id', async (req, res) => {
    try {
      const updatedNote = await noteService.update(req.params.id, req.body);
      if (!updatedNote) return res.status(404).send('Note not found');
      res.status(200).json(updatedNote);
    } catch (error) {
      res.status(500).send(error.message);
    }
  });
}

