import { Note } from '../types';

const notes: Note[] = [];

export const createNote = (note: Note): Note => {
  const newNote = { ...note, id: Date.now().toString() };
  notes.push(newNote);
  return newNote;
};

export const getNotes = (): Note[] => {
  return notes;
};

export const updateNote = (id: string, updatedNote: Note): Note | undefined => {
  const index = notes.findIndex(note => note.id === id);
  if (index !== -1) {
    notes[index] = { ...updatedNote, id };
    return notes[index];
  }
  return undefined;
};

export const deleteNote = (id: string): void => {
  const index = notes.findIndex(note => note.id === id);
  if (index !== -1) {
    notes.splice(index, 1);
  }
};

import express from 'express';
import { createNote, getNotes, updateNote, deleteNote } from '../services/noteService';
import { Note } from '../types';

const noteRouter = express.Router();

noteRouter.get('/', (req, res) => {
  const notes = getNotes();
  res.json(notes);
});

noteRouter.post('/', (req, res) => {
  const note: Note = req.body;
  const newNote = createNote(note);
  res.status(201).json(newNote);
});

noteRouter.put('/:id', (req, res) => {
  const id = req.params.id;
  const updatedNote: Note = req.body;
  const result = updateNote(id, updatedNote);
  if (result) {
    res.json(result);
  } else {
    res.status(404).send('Note not found');
  }
});

noteRouter.delete('/:id', (req, res) => {
  const id = req.params.id;
  deleteNote(id);
