        }
      }
    },
    '/notes': {
      method: 'GET',
      handler: (req, res) => {
        const notes = notesService.getNotes();
        res.send({ notes });
      }
    },
    '/notes/:id/update': {
      method: 'PUT',
      handler: (req, res) => {
        const { title, content } = req.body;
