	"crypto/sha256"
	"fmt"
	"io"
	"os"

	"a-go-cli-tool-that-computes-the-sha-256-hash-of-a-file/internal/fileutil"
)

func GenerateSHA256Go(filename string) {
	file, err := fileutil.OpenRead(filename)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
		return
	}
	defer file.Close()

	hasher := sha256.New()
	if _, err := io.Copy(hasher, file); err != nil {
		fmt.Fprintf(os.Stderr, "Error reading file: %v\n", err)
		return
	}

	fmt.Printf("%x\n", hasher.Sum(nil))
}

