var biggestFiles = []struct{ name string; size int64 }{{" ", 0}}

func (*walker) CheckSize(filePath string, size int64) bool {
	for i, f := range biggestFiles {
		if f.size < size {
			biggestFiles = append(append(biggestFiles[:i], {filePath, size}), biggestFiles[i+1:]...)
