export const parseLines = async (path) => {
  if (!path || path === '-') {
    throw new Error('Input not provided');
  }
  try {
    return (await asyncReadFile(path)).split('\n').filter(line => line.trim().length > 0);
  } catch (_) {
    // Handle the error appropriately, e.g., rethrow with a more detailed message
    throw new Error(`Failed to read input from ${path}`);
  }
};

export const writeResult = async (lines, output) => {
  lines.forEach(line => { output.write(`${line}\n`); });
};

