export function parseLog(logLine: string): { level: string; module: string; message: string } {
  const parts = logLine.split(' ');
  return {
    level: parts[1],
    module: parts[2],
    message: parts.slice(3).join(' '),
  };
}

import { parseLog } from './logParser';

export function countLevels(logLines: string[]): { [key: string]: number } {
  const counts: { [key: string]: number } = {};
  for (const line of logLines) {
    const { level } = parseLog(line);
    counts[level] = (counts[level] || 0) + 1;
  }
  return counts;
}

import { countLevels } from './logCounter';

export function reportTopModules(logLines: string[], topN: number): { module: string; count: number }[] {
  const counts = countLevels(logLines);
  return Object.entries(counts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, topN)
    .map(([module, count]) => ({ module, count }));
}

