export function parseLog(log: string): LogEntry[] {
  const entries: LogEntry[] = [];
  const lines = log.split('\n');
  for (const line of lines) {
    const match = line.match(/\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] \[(\w+)\] (.*)/);
    if (match) {
      entries.push({
        timestamp: match[1],
        level: match[2],
        message: match[3],
        module: '',
      });
    }
  }
  return entries;
}

export function countLevels(logEntries: LogEntry[]): LevelCounts {
  const counts: LevelCounts = {};
  for (const entry of logEntries) {
    if (counts[entry.level]) {
      counts[entry.level]++;
    } else {
      counts[entry.level] = 1;
    }
  }
  return counts;
}

type LogEntry = {
  level: string;
  message: string;
  module: string;
  timestamp: string;
};

type LevelCounts = {
  [level: string]: number;
};

export function reportTopModules(logData: LogEntry[], count: number): ModuleReport[] {
  const moduleCounts: { [key: string]: number } = {};
  for (const entry of logData) {
    if (entry.level === 'error') {
      const module = extractModuleFromMessage(entry.message);
      if (moduleCounts[module]) {
        moduleCounts[module]++;
      } else {
        moduleCounts[module] = 1;
      }
    }
  }
  const sortedModules = Object.entries(moduleCounts).sort((a, b) => b[1] - a[1]);
  const topModules = sortedModules.slice(0, count).map(([module, count]) => ({ module, count }));
  return topModules;
}

function extractModuleFromMessage(message: string): string {
  const moduleMatch = message.match(/module=(\w+)/);
  return moduleMatch ? moduleMatch[1] : 'unknown';
}

type LogEntry = {
  level: string;
  message: string;
  module: string;
  timestamp: string;
};

type ModuleReport = {
  module: string;
  count: number;
};

import { parseLog, countLevels } from './logParser';
import { reportTopModules } from './moduleReport';

export function run(input: string): void {
  try {
    const logLines = input.split('\n');
    const parsedLog = parseLog(logLines.join('\n'));
    const levelsCount = countLevels(parsedLog);
    const topModules = reportTopModules(parsedLog, 3);

    console.log('Log levels count:', levelsCount);
    console.log('Top modules by error count:', topModules);
  } catch (error) {
    console.error('Error processing log:', error.message);
  }
}

export function main(): void {
  const input = process.argv[2] || '';
  run(input);
}

