            var json = System.Text.Json.JsonSerializer.Serialize(contacts, 
                new JsonSerializerOptions{ WriteIndented = true });
            File.WriteAllText(filename, json);

            // Ensure the file size is not zero after writing
            if (System.IO.File.Exists(filename)) {
                var size = System.IO.File.GetAttributes(filename).Length;
                return size != 0 ? contacts.Count : -1; ;
            }
        }

        public IEnumerator<Contact> GetEnumerator() => ((IEnumerable<Contact>)contacts);

        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
