using System;
using System.Collections.Generic;

namespace ContactManagerCLI
{
    public class SearchCommand
    {
        private static List<Contact> _contacts;

        public SearchCommand()
        {
            // Initialize contacts data from JSON file if available 
            var contactRepository = new ContactRepository();
            _contacts = contactRepository.GetContacts();            
        }

        public void Execute(string[] args)
        {
            var queryParameters = ParseArgs(args);

            Console.WriteLine("Searching Contacts...");

            List<Contact> filteredResults = FilterAndSortContacts(queryParameters);

            if (filteredResults.isEmpty()) 
                Console.WriteLine("No results found.");
            else
                foreach (var item in filteredResults) 
                    Console.WriteLine(item.ToString());

        }

        private static QueryParameters ParseArgs(string[] args)
        {
            // Default values for parameters
            var namesearch = string.Empty;
            var sortby = "Name";

            if (!(args.Length >= 2))
                throw new ArgumentException();

            namesearch = args[0];

            if (args.Length > 2) 
                sortby = args[1];

            return new QueryParameters {
                Name = namesearch, 
                SortBy = sortby,
                OrderBy = QueryOrderBy.Ascending
            };
        }

        private List<Contact> FilterAndSortContacts(QueryParameters queryParameters)
        {
            var contacts = new List<Contact>(_contacts); 

            if (!string.IsNullOrEmpty(queryParameters.Name))
                contacts.RemoveAll(x => !x.Name.Contains(queryParameters.Name));

            if (queryParameters.SortBy != null && queryParameters.OrderBy != null) 
                switch( queryParameters.OrderBy )
                {                    
                    case QueryOrderBy.Ascending:
                        contacts = contacts.OrderBy(c => c.Name).ToList();
                        break;

                    case QueryOrderBy.Descending:   
                        contacts = contacts.OrderByDescending(c => c.Name).ToList() ;
                        break;  
                }

            return contacts;
        }
    }

    public class QueryParameters
    {
        public string Name { get; set; }
        public string SortBy { get; set; } 
        public QueryOrderBy OrderBy { get; set; }

        // Enumeration for sorting directions
        public enum QueryOrderBy
        { 
            Ascending,
            Descending           
        }
    }
}

