import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;

public class dataPersistence {
    private static final String TASK_FILE_PATH = "tasks.txt";

    public static List<String> readFromFile(File file) throws IOException {
        if (!file.exists()) return new ArrayList<>();

        try (var bufferedReader = new java.io.BufferedReader(new java.io.FileReader(TASK_FILE_PATH))) {
            var jsonStr = "";
            for(var line : Files.readAllLines(file.toPath()))
                jsonStr +=line;

            JSONObject jsonObject;
            try {

                jsonObject = new JSONObject(jsonStr);
            } catch (Exception e) {
                jsonObject = new JSONObject();
                jsonObject.put("tasks", new JSONArray());
            }

             return readTasksFromJson(jsonObject.getJSONArray("tasks"));
        }
    }

    private static List<String> readTasksFromJson(JSONArray tasksJsonArray){
        if(tasksJsonArray == null)
            return new ArrayList<>();

         List<String> tasks = new ArrayList<>();
         for (int i = 0; i < tasksJsonArray.length(); i++) {
             JSONObject taskObj = tasksJsonArray.getJSONObject(i);
             String text = taskObj.getString("text");
             String statusString = taskObj.optString("status", "Incomplete");
             if(statusString.equals(""))
                text += " - Status: Incomplete";

                 tasks.add(text + " - Status: " + statusString);
         }
        return tasks;
    }

    public static void writeToFile(File file, List<String> tasks) throws IOException {
        List<String> currentTasks = new ArrayList<>();
        try(var bufferedReader  = new java.io.BufferedReader(new java.io.FileReader(TASK_FILE_PATH))) {
            for(final String line : Files.readAllLines(file.toPath())) 
                currentTasks.add(line);

            JSONObject jsonContent = new JSONObject();
            JSONArray tasksJsonArray = new JSONArray();

            var i=0;
             for (String task : tasks) {
                 String[] parts = task.split(" - Status:");
                  if(parts.length == 2)
                     currentTasks.set(i,parts[1].trim() + " - Status:" + "Incomplete");
                     else   currentTasks.add(0 ,task); // handle new tasks

                final JSONObject taskObj = new JSONObject();
                taskObj.put("text", parts[0]);
                if(parts.length == 2)
                    taskObj.put("status", parts[1].trim());

                 tasksJsonArray .put(taskObj);
               ++i;
             }
            jsonContent.put("tasks", tasksJsonArray );

            String content = jsonContent.toString();

            try(var writer = Files.newBufferedWriter(file.toPath())) {
                writer.write(content);  
               } 
        except (final IOException e) {throw new RuntimeException(e);} 
    }

}
}

