public class TaskManager {
    private List<String> tasks = new ArrayList<>();

    public void run(String[] args) {
        if (args.length == 0) {
            System.out.println("Please provide a command: add, list or complete");
            return;
        }

        String command = args[0];
        switch (command.toLowerCase()) {
            case "add": 
                addTask(args);
                break;
            case "list":
                listTasks();
                break;
            case "complete":
                completeTask(Integer.parseInt(args[1]));
                break;
            default:
                System.out.println("Invalid command: use 'add', 'list' or 'complete'");
        }
    }

    private void addTask(String[] args) {
        if (args.length < 2) {
            System.err.println("Please provide a task to add.");
            return;
        }

        String task = " ".join(args, 1);
        tasks.add(task);

        try {
            dataPersistence.writeToFile(tasks.toString());
        } catch (Exception e) {
            System.err.println("Failed to write task. Error: " + e.getMessage());
        }
    }

    private void listTasks() {
        if (tasks.isEmpty()) {
            System.out.println("No tasks found.");
            return;
        }

        for (int i = 0; i < tasks.size(); ++i) {
            String task = tasks.get(i);
            System.out.println((i + 1) + ": " + task);
        }
    }

    private void completeTask(int index) {
        if (index <= 0 || index > tasks.size()) {
            System.err.println("Invalid task index.");
            return;
        }

        String completed = tasks.get(index - 1);
        tasks.remove(index - 1);

        try {
            dataPersistence.writeToFile(tasks.toString());
        } catch (Exception e) {
            System.err.println("Failed to commit complete. Error: " + e.getMessage());
        }
    }
