)

func Main(out, in io.Writer) error {
	app := cli.App{
		Name:   "search",
		Action: func(c *cli.Context) error {
			if len(c.Args()) < 1 {
				return errors.New("search term not provided")
			}

			searchTerm := c.Args().First()

			notes, err := storage.LoadNotes()
			if err != nil {
				return fmt.Errorf("failed to load notes: %w", err)
			}

			var matches []storage.Note
			for _, note := range notes {
				if strings.Contains(strings.ToLower(note.Title), strings.ToLower(searchTerm)) ||
					strings.Contains(strings.ToLower(note.Body), strings.ToLower(searchTerm)) {
					matches = append(matches, note)
				}
			}

			jsonBytes, err := json.MarshalIndent(matches, "", "  ")
			if err != nil {
				return fmt.Errorf("failed to marshal notes: %w", err)
			}

			fmt.Fprintln(out, string(jsonBytes))
			return nil
		},
