	"fmt"
	"os"

	note "github.com/example/vaca-note-manager/notefile"
)

type Note struct {
	Title string `json:"title"`
	Text  string `json:"text"`
}

func readNotes() ([]Note, error) {
	jsonData, err := os.ReadFile("notes.json")
	if err != nil && !os.IsNotExist(err) {
		return nil, fmt.Errorf("reading %s: %w", "notes.json", err)
	}
	var notes []Note
	err = json.Unmarshal(jsonData, &notes)
	if err == nil {
		return notes, nil
	}
	return []Note{}, nil
}

func writeNotes(notes []Note) error {
	jsonData, _ := json.MarshalIndent(notes, "", "\t")
	err := os.WriteFile("notes.json", jsonData, 0644)
	if err != nil {
		return fmt.Errorf("writing %s: %w", "notes.json", err)
	}
	return nil
}

func addNote(title string) error {
	noteToAdd := Note{Title: title, Text: ""}
	_, _ = readNotes()
	err := writeNotes([]Note{noteToAdd})
	if err != nil {
		return fmt.Errorf("adding note '%s': %w", title, err)
	}
	fmt.Println(fmt.Sprintf("Added note: %s", title))
	return nil
}

func listNotes() []Note {
	noteSlice, _ := readNotes()
	for _, n := range noteSlice {
		fmt.Printf("%d. {title: '%s', text: '*REDACTED*'}\n", len(noteSlice), n.Title)
	}
	return noteSlice
}

func searchNotes(term string) ([]Note, error) {
	var results []Note

	for _, n := range readNotes() {
		if strings.Contains(strings.ToLower(n.Title), strings.ToLower(term)) || strings.Contains(strings.ToLower(n.Text), strings.ToLower(term)) {
			results = append(results, n)
		}
	}

	return results, nil
}

func main() {
	cmd := flag.String("cmd", "", "command to execute")
	flag.Parse()

	switch *cmd {
	case "add":
		if len(os.Args) < 3 || os.Args[2] == "" {
			fmt.Println("Add requires a note.")
			os.Exit(1)
		}
		err := addNote(flag.Arg(2))
		if err != nil {
			fmt.Printf("Error: %s\n", err)
			os.Exit(1)
		}
	case "list":
		listNotes()
	default:
		usage()
	}

	os.Exit(0)
}

func usage() {
	fmt.Println("Usage:")
	fmt.Println("\tcli notes add [title]")
	fmt.Println("\tcli notes list")
}

