type Note struct {
	Title  string `json:"title"`
	Text   string `json:"text"`
}

func AddNote(noteTitle string, noteContent string) (string, error) {
	note := Note{
		Title:  noteTitle,
		Text:   noteContent,
	}
	fileName := fmt.Sprintf("%s.json", note.Title)
	data, err := json.MarshalIndent(&note, "", "\t")
	if err != nil {
		return "", err
	}
	err = os.WriteFile(fileName, data, 0644)
	if err != nil {
		return fileName, err
	}
	return fileName, nil
}

func ListNotes() ([]Note, error) {
	var notes []Note

	readErr := readNotes()
	if readErr == nil && len(readNotes()) > 0 {
		return readNotes(), nil
	}

	for _, entry := range os.ReadDir(".") {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") && entry.Name() != "notes.json" {
			jsonData, err := os.ReadFile(fmt.Sprintf("%s/%v", currentDir(), entry.Name()))
			if err == nil {
				var note Note
				err = json.Unmarshal(jsonData, &note)
				if err == nil {
					notes = append(notes, note)
				}
			}
		}
	}

	return notes, nil

func SearchNote(searchQuery string) ([]Note, error) {
	var matchingNotes []Note
	searchString := strings.ToLower(searchQuery)

	for _, n := range readNotes() {
		if strings.Contains(strings.ToLower(n.Title), searchString) || strings.Contains(strings.ToLower(n.Text), searchString) {
			matchingNotes = append(matchingNotes, n)
		}
	}

	return matchingNotes, nil

func currentDir() string {
	dirname, err := os.Getwd()
	if err != nil {
		panic(err)
	}
	return dirname
}
}
