func SearchNotesCommand(query []string) []types.Note {
	return storage.SearchNotesByTerm([]string{query[0]})
}

// Custom function to search notes by a specific term
func SearchNotesByTerm(query []string) (results []types.Note) {	
	data, err := json.Marshal(storage.LoadAllNotes())
	if err != nil {
		fmt.Printf("Error loading all notes: %s\n", err)
		return
	}
	err = json.Unmarshal(data, &results)
	if err != nil {
		fmt.Printf("Error unmarshalling JSON data: %s\n", err)
		return
	}

	for _, note := range results {
		found := false
		tagMatched := false

        // Check for matching content regardless of case.
		if strings.Contains(strings.ToLower(note.Msg), query[0]) {
			results = append(results, note)
            found = true
    	}

    	tags := []string{}
    	if len(note.Tags) > 0 {
            tags = storage.ConvertTagsStringToSlice(note.Tags)

			for _, tag := range tags { // Add a search based on tags as well in case the storage doesn't have that capability.
				if strings.Contains(strings.ToLower(tag), query[0]) == true {
                    results = append(results, note)
					found = true
                }
	           tagMatched = true 
			}    
    	}
      // Return only unique notes based on content matches and tags match. This avoids duplicates in search output.
		if found || tagMatched {  
            fmt.Printf("Tag: %v\n", note.Tags)
            results = append(results, note)        
        }

	return
}

// Convert the string of list tags into a slice for parsing by the storage package
func ConvertTagsStringToSlice(tagInput string) []string {
	var tags []string

    // Split on commas.
	tagsList := strings.Split(tagInput, ",")
	for _, tagItem := range tagsList { // Strip trailing and leading whitespace from each.
		tagItem = strings.TrimSpace(tagItem)
		 if len(tagItem) > 0{
		 	tags = append(tags, tagItem) 
		 }
	}
    return tags
}
}

