package types

import (
	"time"
)

type Note string // A simple string type to represent a note

type AddCommand struct {
	Title   string `json:"title"`  // Title of the note
	Content Note    `json:"content"` // Content of the note
	Tags []string     `json:"tags,omitempty"` // Tags for searching and organizing notes (optional)
}

// ListCommand is not needed here as we are focusing on shared types/interfaces

type SearchCommand struct {
	Query string `json:"query"`
	By   string  `json:"by,omitempty"`
	Limit int    `json:"limit,omitempty"`
}

// NoteStorage defines the file system interactions for storing notes
type NoteStorage interface {
	SaveNote(note AddCommand) error // Method to save a new note in storage
	UpdateNotes() ([]AddCommand, error) // Load and return all existing notes from storage
	GetNotesByTag(tag string) (addCommands []AddCommand, err error) // Find and load specific notes by tag

	FindNotes(filter searchFilter) (notes []AddCommand, matchCount int)
}

// NoteFinder implements the FindNotes filter for searching notes in the storage layer
type NoteFinder struct {
	filter     SearchCommand        `json:"filter"`
	matchedBy  string               `json:"matchedBy"`   // How many criteria matched - by title or content
	totalMatched int                `json:"totalMatched"` // Total matches found across all filters

	notes []AddCommand              // Found notes to return from FindNotes method call
}

