	args := os.Args[1:]
	if len(args) < 2 {
		fmt.Println("Usage: note-manager [add|list|search] [flags]")
		os.Exit(1)
	}

	cmd := args[0]
	switch cmd {
	case "add":
		note := &Note{
			Title:    args[1],
			Content: string(os.Stdin.ReadAll()),
			Tags:     []string{},
			State:    NOTE_ACTIVE,
			Priority: 5,
			CreatedAt: time.Now().Unix(),
		}
		err := repository.AddNote(note)
		if err != nil {
			fmt.Println(err.Error())
			os.Exit(1)
		}
	case "list":
		allNotes, _ := repository.ListAllNotes()
		for _, n := range allNotes {
			fmt.Println(fmt.Sprintf("%d. %s", n.ID, n.Title))
		}
	case "search":
		results, err := repository.SearchNotes(args[1])
		if err != nil {
			fmt.Println(err.Error())
			os.Exit(1)
		}
		for _, r := range results {
			fmt.Println(fmt.Sprintf("%d. %s", r.ID, r.Title))
		}
	default:
		fmt.Printf("Unknown cmd: %s\n", cmd)
		os.Exit(1)
	}
}

