from typing import AnyStr, List

class AppError(Exception):
    def __init__(self, message: str = "", code: int = 500):
        self.message = message
        self.code = code

class Task:
    def __init__(self, description: str, priority: int = 1):
        self.description = description
        self.priority = max(0, priority)

@dataclass(frozen=False)
class TaskManager:

    tasks: list[Task] = field(default_factory=list)

    @classmethod
    def load_from_json(cls, json_path: AnyStr) -> 'TaskManager':
        try:
            with open(json_path, 'r') as file:
                data = json.load(file)
            return cls([Task(d['description'], max(1, int(d.get('priority', 1)))) for d in data])
        except (FileNotFoundError, json.JSONDecodeError) as e:
            raise AppError(str(e))

    def add_task(self, description: str, priority: int = 1):
        self.tasks.append(Task(description=description, priority=max(1, priority)))

    def remove_task(self, task_id: AnyStr) -> bool:
        for idx, t in enumerate(self.tasks):
            if t.description == task_id:
                del self.tasks[idx]
                return True
        return False

    def list_tasks(self) -> List[Task]:
        sorted_by_priority = sorted(self.tasks, key=lambda x: (x.priority, x.description))
        yield from [t for t in sorted_by_priority]

