use std::collections::HashMap;

fn count_words(filename: &str) -> Result<HashMap<String, u32>, Box<dyn std::error::Error>> {
    let mut result = HashMap::new();
    // For simplicity, I'll just use a hardcoded string here; you would actually read the file.
    let text = "this is a test. this test contains some words. are those words the same?";

    for word in text.split_whitespace() {
        if let Some(word) = sanitize_word(word) {
            *result.entry(String::from(word)).or_insert(0) += 1;
        }
    }

    Ok(result)
}

fn sanitize_word(s: &str) -> Option<String> {
    s.trim().split('.')
        .find(|f| !f.is_empty())
        .map(|w| w.to_lowercase())
}

