def scan_directory(path):
    """Recursively scans a directory and returns a list of all regular files."""
    import os
    regular_files = []
    for root, _, filenames in os.walk(path):
        for filename in filenames:
            file_path = os.path.join(root, filename)
            if os.path.isfile(file_path):
                regular_files.append(os.path.relpath(file_path, path))
    return sorted(regular_files)

def find_duplicates(files):
    """Finds groups of duplicate files by comparing inode numbers."""
    duplicates = set()
    seen = {}

    # First pass: group by size
    size_groups = {}
    for file in files:
        stat_info = os.stat(file)
        size = stat_info.st_size

        if size not in size_groups:
            size_groups[size] = []

        # Group by inode numbers (i.e., link count and inode are the same).
        if stat_info.ino not in seen:
            seen[stat_info.ino] = set()

    return duplicates

