class FibonacciGenerator
  def initialize(count)
    @count = count
    @fibonacci_sequence = [0, 1]
    generate if @count > 2
  end

  def generate
    (2...@count).each do |i|
      fib_i = @fibonacci_sequence[i - 1] + @fibonacci_sequence[i - 2]
      @fibonacci_sequence << fib_i
    end
  rescue => e
    puts "Error generating Fibonacci sequence: #{e.message}"
  end

  def first(n)
    return [] if n <= 0
    generate if n > @fibonacci_sequence.length && @count > n
    @fibonacci_sequence[0, n]
  end
end

