async fn start_server(port: &str) -> Result<(), Box<dyn std::error::Error>> {
    // Run the server in a separate process and wait for it to exit.
    let mut cmd = Command::new("cargo");
    cmd.args(&["run", "--bin=srv"]).current_dir(std::env!("CARGO_MANIFEST_DIR"));

    cmd.stdout(Stdio::inherit()).stderr(Stdio::inherit());

    match cmd.spawn() {
        Ok(mut child) => {
            eprintln!("Server started on {}:5001...", port);

            // Wait for the server to exit.
            let status = child.wait().expect("Failed to wait for server process");
            eprintln!("Server exited with status: {}", status);

            match std::fs::read_to_string(format!("/tmp/vaca-rustgate-srv.out")) {
                Ok(output) => println!("{}", output),
                Err(_) => println!("Could not read server response; check the server and /tmp/vaca-rustgate-srv.out"),
            }
