import { generate, checkStrength } from './password';

export function generatePassword(length: number) {
  return generate(length);
}

export function checkPasswordStrength(password: string) {
  return checkStrength(password);
}

export function generate(length: number): string {
  const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+[]{}|;:,.<>?';
  let password = '';
  for (let i = 0; i < length; i++) {
    const randomIndex = Math.floor(Math.random() * characters.length);
    password += characters[randomIndex];
  }
  return password;
}

export function checkStrength(password: string): string {
  if (password.length < 8) return 'Weak';
  if (/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*()_+\[\]{}|;:,.<>?]).{8,}$/.test(password)) return 'Strong';
  return 'Medium';
}

export function randomChar(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  return chars[Math.floor(Math.random() * chars.length)];
}

export function generateRandomString(length: number): string {
  let result = '';
  for (let i = 0; i < length; i++) {
    result += randomChar();
  }
  return result;
}

