export function loadTodos(): TodoItem[] {
  try {
    const todosPath = path.join(dataPath, 'todos.json');
    const data = fs.readFileSync(todosPath, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    return [];
  }
}

export function saveTodos(todos: TodoItem[]): void {
  try {
    const todosPath = path.join(dataPath, 'todos.json');
