guard !args.isEmpty else {
    print("Usage: swift calc.swift <expression>")
    exit(1)
}

func isOperator(_ ch: Character) -> Bool {
    return "+-*/".contains(ch)
}
// ... (remaining code from Calc.swift)

do {
    let expression = args.first!
    let result = try evaluate(expression)
    print(result)
} catch {
    print("Error \(error)")
}

func evaluate(_ expression: String) throws -> Double {
    let tokens = tokenize(expression)
    return try parse(tokens).evaluate()
}

func tokenize(_ input: String) -> [String] {
    var index = 0
    var tokens: [String] = []

    while index < input.count && !CharacterSet.whitespacesAndNewlines.contains(input[input.index(input.startIndex, offsetBy: index)].unicodeScalars.first!) {
            index += 1
