import Foundation

class Evaluator {
    func evaluateTokens(tokens: [String]) -> Double? {
        guard let firstToken = tokens.first else { return nil }
        var stack: [(String, Double)] = []

        for token in tokens {
            if let number = Double(token) {
                stack.append((token, number))
            } else if ["+", "-", "*", "/"].contains(token) {
                switch token {
                case "+":
                    guard let rhs = stack.popLast()?.1,
                          let lhs = stack.last?.1 else { return nil }
                    stack[stack.count - 1] = (token, lhs + rhs)
                case "-":
                    guard let rhs = stack.popLast()?.1,
                          let lhs = stack.last?.1 else { 
                            return nil 
                        };  
                    stack[stack.count - 1] = ("-", lhs - rhs)      
                case "*":
                    guard let rhs = stack.popLast()?.1,
                          let lhs = stack.last?.1 else {
                        return nil
                    }
                    stack[stack.count - 1] = ("*", lhs * rhs)
                case "/":
                    guard let rhs = stack.popLast()?.1,
                          let lhs = stack.last?.1,
                          rhs != Double(0) else { 
                            return nil;  
                       };                            
                    stack[stack.count - 1] = ("/", lhs / rhs)
                }
            }                
        }

        if let result = stack.last?.1 {
           return result
        }

        return nil
    }
}

