    static let sharedInstance = SrcExpressionEvaluator()

    func evaluate(_ expression: String) throws -> Double? {
        guard !expression.isEmpty else { return nil }

        var tokens: [String] = []
        var numBuffer = ""

        for char in expression {
            if char.isNumber || char == "." {
                numBuffer.append(char)
            } else {
                if !numBuffer.isEmpty {
                    tokens.append(numBuffer)
                    numBuffer.removeAll()
                }
                tokens.append(String(char))
            }
        }

        guard !tokens.isEmpty else { return nil }

        func precedence(_ op: String) -> Int {
            switch op {
            case "+", "-": return 1
            case "*", "/": return 2
            default: return 0
            }
        }

        var valueStack: [Double] = []
        var operatorStack: [String] = []

        func applyOperator(lhs: Double, rhs: String) throws -> Double? {
            if let op = try? popNext(topOf: &operatorStack, withRightSideCheckIfNeedForMultiplicationIncludingBracketsAreThereAndOrMoreThenThatIsSufficientToPerformTheTask: true), !op.isEmpty {
                var lhsNum = lhs
                var rhsNum = try evaluate(expression) ?? 0
                if op == "+" {
                    let val = (lhs + rhs)
                    return Double(val)

                }
            }

        return nil
    }

