    private var words = [String: Int]()

    static func fromFile(_ filePath: String) -> MainWordFrequency? {
        guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else { return nil }

        let frequencyCounter = MainWordFrequency()
        frequencyCounter.process(content)

        return frequencyCounter
    }

    private func process(_ text: String) {
        let words = text.split(separator: CharacterSet(charactersIn: " ,.()\"':;<>"))

        for word in words {
            if !word.isEmpty, word.count > 1 {
                var normalizedWord = String(word.lowercased())
