import Foundation

struct WordFrequency {
    var path: String

    private func loadTextData() throws -> Dictionary<String, Int> {
        let text = try FileManager.default.contentsOfDirectory(atPath: self.path).joined(separator: " ")
        return parseWords(text.lowercased().split(separator: .whitespaces))
    }

    func calculateWordFrequency() throws -> [(word: String, frequency: Int)] {
        guard let counts = loadTextData() else { throw NSError(domain: "No data loaded", code: 1) }
        var sortedCounts = Array(counts).sorted(by: { $0.value > $1.value })
        return formatOutput(sortedCounts)
    }

    private func parseWords(_ text: Substring) -> Dictionary<String, Int> {
        let counts = [String: Int]()

        for word in String(text.lowercased()).components(separatedBy: .whitespacesAndNewlines).filter({ $0.count > 1 }) {
            counts[String(word), default: 0] += 1
        }

        return counts
    }

    private func formatOutput(_ sortedCounts: [(word: String, frequency: Int)]) -> [(word: String, frequency: Int)] {
        let maxResults = min(sortedCounts.count, 5)
        var result = String()

        for entry in sortedCounts.prefix(maxResults) {
            result.append("\(entry.word): \(entry.frequency)\n")
        }

        return Array(result.split(separator: .newlines))
    }
}

