class Counter {
    func countWords(in text: String) -> [String: Int] {
        var wordCount = [String: Int]()

        let words = clean(text).split(separator: " ").map { String($0) }

        for word in words {
            wordCount[word, default: 0] += 1
        }

        return wordCount
    }

    func clean(_ input: String) -> String {
        var cleaned = ""
        let punctuation = [" ", ".", ",", "!", "?", "\""]

        for char in Array(input.lowercased()) {
            if char.isLetter || char == "'" {
                cleaned.append(char)
            } else if punctuation.contains(String(char)) && !cleaned.isEmpty, let last = cleaned.last as Character {
                guard last == "." else { continue }
                cleaned.append(" ")
            }
        }

        // Remove any consecutive spaces and add a space at the end
        return String(cleaned.split(separator: " ").joined(separator: " ")) + " "
    }

    func format(count map: [String : Int]) -> [String] {
        var output = "\nWord Frequency Count results:\n\n"

        for (key, count) in map { 
            output.append("\(count)\t\(key)\n") 
        }

        return [output]
    }

    func run(filePath: String?) throws -> [String] {
        guard let path = filePath else { throw Error.invalidInput }

        // Read input
        var buffer = ""

        if let file = try? FileHandler.fileRead(at: "path/to/text.txt") {

            // Process data
            defer { buffer.removeLast() }  // Remove the trailing newline

            for char in Array(file) {
                if char.isLetter || char == "'" {
                    buffer.append(char)
                } else if [" ", ".", ",", "!", "?", "\""].contains(String(char)) && !buffer.isEmpty, let last = buffer.last as Character {
                    guard last != "." else { continue }
                    buffer.append(" ")
                }
            }

        } else { throw Error.invalidFile }

        // Build result
        var wordsFrequency = [String: Int]()

        for word in String(buffer.split(separator: " ").joined(separator: " ")) {
            wordsFrequency[word, default: 0] += 1
        }

        return format(count: wordsFrequency)
    }

    enum Error : Swift.Error { case unknown, invalidInput, outOfMemory, fileTooLarge, fileNotFound }

}
