export interface GameState {
  board: string[];
  currentPlayer: 'X' | 'O';
  isGameOver: boolean;
  winner?: 'X' | 'O' | 'Draw';
}

export class GameLogic {
  private board: string[];
  private currentPlayer: 'X' | 'O';
  private _isGameOver: boolean;
  private winner?: 'X' | 'O' | 'Draw';

  constructor() {
    this.board = Array(9).fill('');
    this.currentPlayer = 'X';
    this._isGameOver = false;
    this.winner = undefined;
  }

  public makeMove(index: number): void {
    if (this._isGameOver || this.board[index] !== '') {
      return;
    }

    this.board[index] = this.currentPlayer;
    this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
    this.checkGameOver();
  }

  public getBoard(): string[] {
    return this.board;
  }

  public getCurrentPlayer(): 'X' | 'O' {
    return this.currentPlayer;
  }

  public isGameOver(): boolean {
    return this._isGameOver;
  }

  public getWinner(): 'X' | 'O' | 'Draw' | undefined {
    return this.winner;
  }

  private checkGameOver(): void {
    const winConditions = [
      [0, 1, 2],
      [3, 4, 5],
      [6, 7, 8],
      [0, 3, 6],
      [1, 4, 7],
      [2, 5, 8],
      [0, 4, 8],
      [2, 4, 6],
    ];

    for (const condition of winConditions) {
      const [a, b, c] = condition;
      if (this.board[a] !== '' && this.board[a] === this.board[b] && this.board[a] === this.board[c]) {
        this._isGameOver = true;
        this.winner = this.board[a] as 'X' | 'O' | 'Draw';
        return;
      }
    }

    if (!this.board.includes('')) {
      this._isGameOver = true;
      this.winner = 'Draw';
    }
  }
}

import { GameLogic, GameState, Board } from '../gameLogic.ts';

export function runGame(): void {
  const game = new GameLogic();
  game.startGame();

  const gameState = game.getGameState();
  const board = new Board(gameState.board);

  console.log('Tic-Tac-Toe Game');
  console.log('Player 1: X');
  console.log('Player 2: O');
