#!/usr/bin/env node

import { DefaultMap } from './scanner.js';
import * as fs from 'fs';

import * as fs from 'fs';
import * as path from 'path';

function walk(dir) {
  const files = [];
  function traverse(d) {
    for (const item of fs.readdirSync(d)) {
      const fullPath = path.join(d, item);
      if (fs.statSync(fullPath).isDirectory()) {
        traverse(fullPath);
      } else {
        files.push(fullPath);
      }
    }
  }
  traverse(dir);
  return files;
}

function hashFile(filePath) {
  const fd = fs.openSync(filePath, 'r');
  const buffer = Buffer.alloc(4096);
  let bytesRead;
  let data = '';
  while ((bytesRead = fs.readSync(fd, buffer, 0, buffer.length)) > 0) {
    data += buffer.slice(0, bytesRead).toString('hex');
  }
  fs.closeSync(fd);
  return data;
}

export function run(dir) {
  const files = walk(dir);
  const hashes = {};
  for (const file of files) {
    try {
      const h = hashFile(file);
      if (!hashes[h]) hashes[h] = [];
      hashes[h].push(file);
    } catch (e) {}
  }
  let printedDupFiles = false;
  for (const group of Object.values(hashes)) {
    if (group.length < 2) continue;
    let sizeBytes = 0;
    try {
      sizeBytes = fs.statSync(group[0]).size;
    } catch (e) {}
    console.log(`DUPLICATE ${sizeBytes}:`, group.join(', '));
    printedDupFiles = true;
  }
  if (!printedDupFiles) console.log('NO_DUPLICATES');
}

