import json
from pathlib import Path

DATA_FILE = Path("expenses.json")

class Expense:
    def __init__(self, category: str, amount: float, description: str):
        self.category = category
        self.amount = amount
        self.description = description

def load_expenses() -> list[Expense]:
    if DATA_FILE.exists():
        with open(DATA_FILE, "r") as f:
            data = json.load(f)
            return [Expense(e["category"], e["amount"], e["description"]) for e in data]
    return []

def save(expenses: list[Expense]) -> None:
    with open(DATA_FILE, "w") as f:
        json.dump([{"category": e.category, "amount": e.amount, "description": e.description} for e in expenses], f)

def add_expense(category: str, amount: float, description: str) -> None:
    expenses = load_expenses()
    expenses.append(Expense(category, amount, description))
    save(expenses)

def list_expenses() -> None:
    for exp in load_expenses():
        print(f"{exp.category}|{exp.amount}|{exp.description}")

def total_amounts() -> None:
    cats = {}
    for exp in load_expenses():
        cats[exp.category] = cats.get(exp.category, 0) + exp.amount
    for cat, total in cats.items():
        print(f"{cat}: {total}")

