package app

import (
	"context"
	"encoding/json"
	"errors"
	"os"

	crypto "crypto/rand"
)

type note struct {
	ID    string `json:"id"`
	Title string `json:"title"`
	Body  string `json:"body"`
}

func loadNotes(ctx context.Context) []note {
	file, err := os.Open("notes.json")
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		panic(err)
	}
	defer file.Close()

	var notes []note
	err = json.NewDecoder(file).Decode(&notes)
	if err != nil {
		panic(err)
	}
	return notes
}

func saveNotes(ctx context.Context, notes []note) error {
	file, err := os.Create("notes.json")
	if err != nil {
		return err
	}
	defer file.Close()
	return json.NewEncoder(file).Encode(notes)
}

