import { Quiz } from './Quiz.js';

export class UI {
  #quiz;
  #questionEl;
  #choicesEl;
  constructor(quizContainerId) {
    this.#quiz = new Quiz();
    this.#questionEl = document.createElement('p');
    this.#choicesEl = document.createElement('div');
    const refreshUI = () => {
      this.#choicesEl.innerHTML = '';
      if (!this.#quiz.hasNext()) return;
      this.#questionEl.textContent = `Question ${this.#quiz.score + 1}: ${this.#quiz.getCurrent()}`;
      this.#quiz.getChoices().forEach((choice, index) => {
        const btn = document.createElement('button');
        btn.textContent = choice.id.toUpperCase();
        btn.onclick = () => { this.#quiz.choose(index); refreshUI(); };
        this.#choicesEl.append(btn);
      });
    };
    quizContainerId && (document.getElementById(quizContainerId)?.append(this.#questionEl, this.#choicesEl));
    refreshUI();
  }
}

