export function deleteTask(id: number): void {
  const tasks = load();
  const updated = tasks.filter((_, i) => id !== i);
  save(updated);
  render(taskList!, counter!);
}

export function markComplete(id: number): void {
  const tasks = load();
  const updated = tasks.map((t, i) => (id === i ? { ...t, done: !t.done } : t));
  save(updated);
  render(taskList!, counter!);
}

