        for (std::size_t j = 0; j + 1 < items.size() - i; ++j) {
            if (items[j] > items[j + 1]) {
                int tmp = items[j];
                items[j] = items[j + 1];
                items[j + 1] = tmp;
            }
        }
    }
    return items;
}

int main() {
    std::vector<int> values{10, 2, 33, 4};
    std::vector<int> sorted = sort_values(values);
    for (std::size_t i = 0; i < sorted.size(); ++i) {
        if (i) {
            std::cout << ',';
        }
        std::cout << sorted[i];
    }
    std::cout << "\n";
    return 0;
}

