}

public class Fibonacci {
    static long[] fib(int n) {
        long[] out = new long[n];
        long a = 0;
        long b = 1;
        for (int i = 0; i < n; i++) {
            out[i] = a;
            long next = a + b;
            a = b;
            b = next;
        }
        return out;
    }

    public static void main(String[] args) {
        long[] values = fib(5);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < values.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(values[i]);
        }
        System.out.println(sb.toString());
    }
}

public class Primes {
