        if (value < 2) {
            return false;
        }
        for (int p = 2; p * p <= value; p++) {
            if (value % p == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        for (int value = 2; value <= 5; value++) {
            if (isPrime(value)) {
                if (!first) {
                    sb.append(',');
                }
                sb.append(value);
