public class Fibonacci {
    static long[] fib(int n) {
        long[] out = new long[n];
        long a = 0;
        long b = 1;
        for (int i = 0; i < n; i++) {
            out[i] = a;
            long next = a + b;
            a = b;
            b = next;
        }
        return out;
    }

    public static void main(String[] args) {
        long[] values = fib(30);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < values.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(values[i]);
        }
        System.out.println(sb.toString());
    }
}

public class Primes {
    static boolean isPrime(int value) {
        if (value < 2) {
            return false;
        }
        for (int p = 2; p * p <= value; p++) {
            if (value % p == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        for (int value = 2; value <= 30; value++) {
            if (isPrime(value)) {
                if (!first) {
                    sb.append(',');
                }
                sb.append(value);
                first = false;
            }
        }
        System.out.println(sb.toString());
    }
}

