func fib(_ n: Int) -> [Int] {
    var a = 0
    var b = 1
    var out: [Int] = []
    for _ in 0..<n {
        out.append(a)
        let next = a + b
        a = b
        b = next
    }
    return out
}

let sequence = fib(15).map { String($0) }
print(sequence.joined(separator: " "))

func isPrime(_ value: Int) -> Bool {
    if value < 2 {
        return false
    }
    var factor = 2
    while factor * factor <= value {
        if value % factor == 0 {
            return false
        }
        factor += 1
    }
    return true
}

let found = (2...15).filter { isPrime($0) }
print(found.map { String($0) }.joined(separator: ","))

