#include <stdio.h>

#define COUNT 3

struct item {
    char name[12];
    int qty;
    double price;
};

static int available(const struct item *items, int count, int *picked) {
    int found = 0;
    for (int i = 0; i < count; i++) {
        if (items[i].qty > 0) {
            picked[found] = i;
            found += 1;
        }
    }
    return found;
}

static double total(const struct item *items, const int *picked, int found) {
    double sum = 0.0;
    for (int i = 0; i < found; i++) {
        sum += items[picked[i]].qty * items[picked[i]].price;
    }
    return sum;
}

int main(void) {
    struct item stock[COUNT] = {
    {"bolt", 12, 0.50},
    {"nut", 40, 0.10},
    {"washer", 0, 0.05},
    };
    int picked[COUNT];
