#include <stdio.h>

#define MAX_PARTS 16
#define COUNT 8

static int factorise(int value, int *parts) {
    int found = 0;
    int divisor = 2;
    while (divisor * divisor <= value && found < MAX_PARTS) {
        while (value % divisor == 0 && found < MAX_PARTS) {
            parts[found] = divisor;
            found += 1;
            value /= divisor;
        }
        divisor += 1;
    }
    if (value > 1 && found < MAX_PARTS) {
        parts[found] = value;
        found += 1;
    }
    return found;
}

static void render(const int *parts, int found) {
    for (int i = 0; i < found; i++) {
        if (i > 0) {
            printf(" x ");
        }
        printf("%d", parts[i]);
    }
}

int main(void) {
    int numbers[COUNT] = {6, 11, 12, 7, 11, 13, 17, 19};
    int parts[MAX_PARTS];
    for (int i = 0; i < COUNT; i++) {
        int found = factorise(numbers[i], parts);
        printf("%d: ", numbers[i]);
        render(parts, found);
        printf("\n");
    }
    return 0;
}

