val VALUES = listOf(3, 1, 4)

class Node(val value: Int, var next: Node? = null)

fun build(values: List<Int>): Node? {
    var head: Node? = null
    for (value in values.reversed()) {
        head = Node(value, head)
    }
    return head
}

fun reverse(head: Node?): Node? {
    var previous: Node? = null
    var current = head
    while (current != null) {
        val following = current.next
        current.next = previous
        previous = current
        current = following
    }
    return previous
}

fun render(head: Node?): String {
    val parts = mutableListOf<String>()
    var cursor = head
    while (cursor != null) {
        parts.add(cursor.value.toString())
        cursor = cursor.next
    }
    return parts.joinToString(" -> ")
}

fun main() {
    val head = build(VALUES)
    println(render(head))
    println(render(reverse(head)))
}

