VALUES = [3, 1, 4]

class Node:
    def __init__(self, value, nxt=None):
        self.value = value
        self.next = nxt

def build(values):
    head = None
    for value in reversed(values):
        head = Node(value, head)
    return head

def reverse(head):
    prev = None
    while head:
        head.next, prev, head = prev, head, head.next
    return prev

def render(head):
    out = []
    while head:
        out.append(str(head.value))
        head = head.next
    return ' -> '.join(out)

head = build(VALUES)
print(render(head))
print(render(reverse(head)))

