NUMBERS = [30, 59, 60, 7, 11, 13, 17, 19]

def factorise(value):
    out = []
    divisor = 2
    while divisor * divisor <= value:
        while value % divisor == 0:
            out.append(divisor)
            value //= divisor
        divisor += 1
    if value > 1:
        out.append(value)
    return out

