TEXT = 'the quick brown fox jumps over the lazy dog the fox'

def words(text):
    return text.split()

def transform(words):
    return [word.capitalize() for word in words]

def longest(words):
    return max(words, key=len) if words else ''

def report(words):
    return ' | '.join(transform(words))

items = words(TEXT)
print(report(items))
print(len(items), longest(items), sum(len(word) for word in items))

