class Account
  attr_reader :log

  def initialize(opening)
    @balance = opening
    @log = [['open', opening, opening]]
  end

  def deposit(amount)
    @balance += amount
    @log << ['deposit', amount, @balance]
  end

  def withdraw(amount)
    if amount > @balance
      @log << ['refused', amount, @balance]
      return false
    end
    @balance -= amount
    @log << ['withdraw', amount, @balance]
    true
  end
end

