account = Account.new(OPS[0][1])
OPS[1..].each do |kind, amount|
  kind == 'deposit' ? account.deposit(amount) : account.withdraw(amount)
end

account.log.each { |kind, amount, balance| puts format('%-9s %4d -> %4d', kind, amount, balance) }

