fn transpose(m: &[[i32; 3]; 3]) -> [[i32; 3]; 3] {
    let mut out = [[0i32; 3]; 3];
    for i in 0..3 {
        for j in 0..3 {
            out[j][i] = m[i][j];
        }
    }
    out
}

fn row_sums(m: &[[i32; 3]; 3]) -> [i32; 3] {
    let mut sums = [0i32; 3];
    for i in 0..3 {
        for j in 0..3 {
            sums[i] += m[i][j];
        }
    }
    sums
}

fn main() {
    let m: [[i32; 3]; 3] = [
    [1, 2, 3],
