struct Stack {
    items: Vec<i32>,
}

impl Stack {
    fn new() -> Stack {
        Stack { items: Vec::new() }
    }

    fn push(&mut self, value: i32) {
        self.items.push(value);
    }

    fn pop(&mut self) -> Option<i32> {
        self.items.pop()
    }

    fn peek(&self) -> Option<i32> {
        self.items.last().copied()
    }
}

fn main() {
    let ops: Vec<String> = vec![
        "push 3".to_string(),
        "push 1".to_string(),
        "peek".to_string(),
