    for value in [5, 9, 2, 6, 1] {
        list.push_front(value);
    }
    println!("{}", list.render());
    list.reverse();
    println!("{}", list.render());
}

struct Node {
    value: i32,
    next: Option<usize>,
}

struct List {
    nodes: Vec<Node>,
    head: Option<usize>,
}

impl List {
    fn new() -> List {
        List { nodes: Vec::new(), head: None }
    }

    fn push_front(&mut self, value: i32) {
        let next = self.head;
        self.nodes.push(Node { value, next });
        self.head = Some(self.nodes.len() - 1);
    }

    fn reverse(&mut self) {
        let mut prev: Option<usize> = None;
        let mut current = self.head;
        while let Some(index) = current {
            let next = self.nodes[index].next;
            self.nodes[index].next = prev;
            prev = Some(index);
            current = next;
        }
        self.head = prev;
    }

    fn render(&self) -> String {
        let mut parts: Vec<String> = Vec::new();
        let mut current = self.head;
        while let Some(index) = current {
            parts.push(self.nodes[index].value.to_string());
            current = self.nodes[index].next;
        }
        parts.join(" -> ")
    }
}

fn main() {
    let mut list = List::new();
    for value in [10, 20, 30, 40] {
        list.push_front(value);
    }
    println!("{}", list.render());
    list.reverse();
    println!("{}", list.render());
}

fn parse(data: &str) -> (Vec<&str>, Vec<(i32, i32)>) {
    let lines: Vec<&str> = data.trim().split('\n').filter(|line| !line.is_empty()).collect();
    let header: Vec<&str> = lines[0].split(',').collect();
    let rows: Vec<(i32, i32)> = lines[1..]
        .iter()
        .map(|line| {
            let fields: Vec<&str> = line.split(',').collect();
            (
                fields[1].parse().unwrap_or(0),
                fields[2].parse().unwrap_or(0),
            )
        })
        .collect();
    (header, rows)
}

fn totals(rows: &[(i32, i32)]) -> (i32, i32) {
    rows.iter().fold((0, 0), |acc, row| (acc.0 + row.0, acc.1 + row.1))
}

