    let (header, rows) = parse("name,qty,price\nbolt,12,1\nnut,40,2\nwasher,0,3");
    let (left, right) = totals(&rows);
    println!("columns {},{}", header[1], header[2]);
    println!("{}: {}", header[1], left);
    println!("{}: {}", header[2], right);
}

