for (const op of OPS.slice(1)) {
  if (op[0] === "deposit") {
    account.deposit(op[1]);
  } else {
    account.withdraw(op[1]);
  }
}

for (const entry of account.log) {
  console.log(entry[0].padEnd(9) + " " + String(entry[1]).padStart(4) + " -> " + String(entry[2]).padStart(4));
}

