                int cache_play(const Op *ops, int count, int capacity,
                               char *out, size_t cap) {
                    const char *keys[8];
                    int used_at[8];
                    int size = 0;
                    int clock = 0;
                    int used = 0;
                    int i;
                    if (capacity > 8) {
                        capacity = 8;
                    }
                    for (i = 0; i < count; i++) {
                        int index = -1;
                        int slot;
                        clock++;
                        for (slot = 0; slot < size; slot++) {
                            if (strcmp(keys[slot], ops[i].key) == 0) {
                                index = slot;
                                break;
                            }
                        }
                        if (strcmp(ops[i].kind, "get") == 0) {
                            if (index >= 0) {
                                used_at[index] = clock;
                                used = append(out, cap, used, "get %s hit\n", ops[i].key);
                                continue;
                            }
                            used = append(out, cap, used, "get %s miss\n", ops[i].key);
                            if (size < capacity) {
                                keys[size] = ops[i].key;
                                used_at[size] = clock;
                                size++;
                            }
                            continue;
                        }
                        if (index >= 0) {
                            used_at[index] = clock;
                            used = append(out, cap, used, "put %s\n", ops[i].key);
                            continue;
                        }
                        if (size < capacity) {
                            keys[size] = ops[i].key;
                            used_at[size] = clock;
                            size++;
                            used = append(out, cap, used, "put %s\n", ops[i].key);
                            continue;
                        }
                        {
                            int oldest = 0;
                            for (slot = 1; slot < size; slot++) {
                                if (used_at[slot] < used_at[oldest]) {
                                    oldest = slot;
                                }
                            }
                            used = append(out, cap, used, "put %s evict %s\n",
                                          ops[i].key, keys[oldest]);
                            keys[oldest] = ops[i].key;
                            used_at[oldest] = clock;
                        }
                    }
                    out[used] = '\0';
                    return used;
                }

