#include "isbn.h"

int isbn_expected(const char *code) {
    int sum = 0;
    int i;
    for (i = 0; i < 9; i++) {
        sum += (code[i] - '0') * (10 - i);
    }
    return (11 - sum % 11) % 11;
}

int isbn_valid(const char *code) {
    int expected = isbn_expected(code);
    char last = code[9];
    if (last == 'X') {
        return expected == 10;
    }
    return expected == last - '0';
}

