void life_step(const int grid[4][4], int next[4][4]) {
    int row;
    int col;
    for (row = 0; row < 4; row++) {
        for (col = 0; col < 4; col++) {
            int live = 0;
            int dr;
            int dc;
            for (dr = -1; dr <= 1; dr++) {
                for (dc = -1; dc <= 1; dc++) {
                    int r;
                    int c;
                    if (dr == 0 && dc == 0) {
                        continue;
                    }
                    r = row + dr;
                    c = col + dc;
                    if (r < 0 || c < 0 || r >= 4 || c >= 4) {
                        continue;
                    }
                    if (grid[r][c]) {
                        live++;
                    }
                }
            }
            if (grid[row][col]) {
                next[row][col] = (live == 2 || live == 3);
            } else {
                next[row][col] = (live == 3);
            }
        }
    }
}

