func ToRoman(n int) string {
    if n <= 0 || n > 3999 {
        return ""
    }
    out := ""
    for _, numeral := range numerals {
        for n >= numeral.Value {
            out += numeral.Symbol
            n -= numeral.Value
        }
    }
    return out
}

func DigitSum(n int) int {
    total := 0
    for n > 0 {
        total += n % 10
        n /= 10
    }
    return total
}

