func Wrap(text string, width int) []string {
    if width <= 0 {
        width = 20
    }
    lines := make([]string, 0, 4)
    current := ""
    for _, word := range Words(text) {
        if len(word) > width {
            word = word[:width]
        }
        if current == "" {
            current = word
            continue
        }
        if len(current)+1+len(word) > width {
            lines = append(lines, current)
            current = word
            continue
        }
        current += " " + word
    }
    if current != "" {
        lines = append(lines, current)
    }
    return lines
}

