    lines := []string{fmt.Sprintf("price %d paid %d change %d", price, paid, paid-price)}
    rest := paid - price
    for _, coin := range coins {
        count := rest / coin
        if count == 0 {
            continue
        }
        rest -= count * coin
        lines = append(lines, fmt.Sprintf("%d x %d", count, coin))
    }
    if rest != 0 {
        lines = append(lines, fmt.Sprintf("leftover %d", rest))
    }
    return lines
}

