public class Isbn {
    public static int expected(String code) {
        int sum = 0;
        for (int i = 0; i < 9; i++) {
            sum += (code.charAt(i) - '0') * (10 - i);
        }
        return (11 - sum % 11) % 11;
    }

    public static boolean valid(String code) {
        int expected = expected(code);
        char last = code.charAt(9);
        if (last == 'X') {
            return expected == 10;
        }
        return expected == last - '0';
    }
}

