const CAPACITY = 2;
const OPERATIONS = [
  { op: 'get', key: 'a' },
  { op: 'put', key: 'b' },
  { op: 'get', key: 'a' },
  { op: 'put', key: 'c' },
  { op: 'get', key: 'b' },
  { op: 'get', key: 'a' },
];

function replay(operations, capacity) {
  const order = [];
  const resident = {};
  const events = [];

  function touch(key) {
    const at = order.indexOf(key);
    if (at >= 0) {
      order.splice(at, 1);
    }
    order.push(key);
  }

  for (let i = 0; i < operations.length; i += 1) {
    const operation = operations[i];
    const key = operation.key;
    if (operation.op === 'get') {
      if (resident[key]) {
        touch(key);
        events.push('get ' + key + ' hit');
      } else {
        events.push('get ' + key + ' miss');
        // A miss fills an empty slot; a full cache is left alone.
        if (order.length < capacity) {
          resident[key] = true;
          order.push(key);
        }
      }
    } else if (resident[key]) {
      touch(key);
      events.push('put ' + key);
    } else {
      let evicted = '';
      if (order.length >= capacity) {
        evicted = order.shift();
        delete resident[evicted];
      }
      resident[key] = true;
      order.push(key);
      events.push('put ' + key + (evicted ? ' evict ' + evicted : ''));
    }
  }
  return events;
}

module.exports = { CAPACITY: CAPACITY, OPERATIONS: OPERATIONS, replay: replay };

